package repoops

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"runtime/debug"
	"time"

	"github.com/entireio/go-nuts/jsconsumer"
	"github.com/entireio/go-nuts/natsmsg"
	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"github.com/oklog/ulid/v2"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	otelcodes "go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"entire.io/core/mirrorrepo"
	"entire.io/core/model"
	"entire.io/slogutil"
)

const (
	// durableBase is the stem of every regional consumer's JetStream
	// durable. New() appends the op and the jurisdiction (e.g.
	// "entirecore-repoops-teardown-eu") so each (op, region) pair gets a
	// DISTINCT durable on the shared central repo_ops_v1 stream.
	//
	// Durable names are unique per stream: all regional cores bind the same
	// central stream and differ only by filter subject, so a shared name
	// would make the second consumer bind the first's filter (or fail to
	// create its own) and silently never drain its own jobs. Replicas of
	// one region's core DO share each durable — that's intended, they
	// split the work. Changing the composed names orphans the existing
	// durables; the teardown names predate suspend/resume and are pinned
	// byte-identical by TestNewFilterAndDurablePerOp.
	durableBase = "entirecore-repoops"

	// dlqSubjectPrefix + <op> + "." + <reason> composes the dead-letter subject
	// repo.ops.dlq.v1.<op>.<reason> that natsmsg.DeadLetter republishes poison to
	// before Acking it off this WorkQueue (COR-944).
	dlqSubjectPrefix = "repo.ops.dlq.v1."

	defaultAckWait = 2 * time.Minute
	// defaultMaxDeliver is unlimited (-1) on purpose, for every op. Each job
	// is published once off its triggering webhook and is NOT re-derivable:
	// GitHub never resends the event, the removal ops delete/clear the
	// github_repos metadata, and no sweep re-enumerates orphaned or suspended
	// placements. With no DLQ, a finite cap would strand the work after a
	// brief regional/data-plane outage — for teardown, orphaned objstore data
	// plus live (exploitable) SpiceDB grants; for suspend, live grants on a
	// detached upstream. A dropped resume differs (the placement stays
	// suspended, and the admin resume tool can recover it by hand), but
	// unlimited is still right: every executor is idempotent and gated, so
	// retrying costs nothing. Unlimited retry rides the outage out;
	// StreamMaxAge (48h) is the final backstop and nakDelay backs the retries
	// off so they don't hammer a recovering store.
	defaultMaxDeliver = -1
	defaultNakDelay   = 5 * time.Second
	defaultFetchBatch = 1

	// nakDelayMax caps the geometric redelivery backoff (see nakDelay). MaxDeliver
	// is unlimited, so this bounds the churn of an op stuck behind an outage while
	// it keeps retrying. This was the consumer's RetryBackoffMx before go-nuts's
	// jsconsumer took over reconnect backoff; it stays a disposition constant since
	// it caps the nak delay, not reconnects.
	nakDelayMax = 30 * time.Second
)

const consumerTracerName = "repoops"

// Teardowner unwinds one mirror placement: data-plane storage, the
// native-repo facet (registry + regional row + SpiceDB grants), and the
// placement tables. *core/api.Server satisfies it via TeardownMirror.
// Must be idempotent — the consumer Naks (redelivers) on any failure.
type Teardowner interface {
	TeardownMirror(ctx context.Context, mirrorID model.RepoID, clusterSlug string) error
}

// Suspender blanks one mirror placement's authz: stamps suspended_at and
// revokes every SpiceDB grant. *core/mirrorrepo.Service satisfies it.
// mirrorrepo.ErrNotFound (placement already gone) Acks instead of Naking;
// any other failure redelivers, so it must be idempotent.
type Suspender interface {
	MarkSuspended(ctx context.Context, id model.RepoID, observedAt time.Time, source string) error
}

// Resumer lifts one mirror placement's suspension and re-materializes its
// grants from the GitHub read-model. *core/api.Server satisfies it via
// ResumeMirror. Same disposal contract as Suspender: ErrNotFound Acks,
// other failures redeliver, so it must be idempotent.
type Resumer interface {
	ResumeMirror(ctx context.Context, mirrorID model.RepoID) error
}

// UpstreamFreshness is the consumer's last-writer-wins gate against the
// global metadata, consulted by BOTH teardown and suspend. RepoReattachedAfter
// reports whether a github_repos row for githubRepoID was observed ATTACHED
// (installation_id set) with synced_at strictly newer than observedAt — i.e.
// a re-add / re-bind upsert superseded the removal that produced this job.
// Attachment is part of the predicate: a newer observation that DETACHED the
// repo (the reconciler's 404-detach landing between the removal webhook's
// receipt and this job's processing, COR-949) corroborates the removal and
// must not supersede it. *githubperms.Service satisfies it; the regional
// core reads github_repos on the global pool it already holds (same access
// pattern as STS mirror resolution), so this is one read, not a call to
// global core.
//
// The gate is the single authoritative point: the producer enqueues
// removal candidates dumbly, and this check — run right before the
// destructive action, against current state — decides whether to proceed.
// It makes a stale removal, or one superseded by a re-add after the job
// was published, skip instead of destroying (or blanking) a live mirror.
type UpstreamFreshness interface {
	RepoReattachedAfter(ctx context.Context, githubRepoID int64, observedAt time.Time) (bool, error)
}

// can't be confused with a re-add supersession — and so a dropped revocation
// can't hide behind either.
func (c *Consumer) skipInstallationUnsuspended(ctx context.Context, job Job) {
	trace.SpanFromContext(ctx).SetAttributes(attribute.Bool("entire.suspend.installation_unsuspended", true))
	slogutil.Info(ctx, "repo-ops suspend skipped: owning installation no longer suspended (unsuspend raced the app-suspend)",
		slog.String("mirror_ulid", job.Target.ULID),
		slog.Int64("github_repo_id", job.GitHubRepoID),
		slog.Int64("installation_id", job.InstallationID),
	)
	recordJobSkipped(ctx, c.cfg.Op, skipReasonInstallationUnsuspended)
}

func (c *Consumer) skipPlacementGone(ctx context.Context, job Job) {
	trace.SpanFromContext(ctx).SetAttributes(attribute.Bool("entire."+string(c.cfg.Op)+".placement_gone", true))
	slogutil.Info(ctx, "repo-ops "+string(c.cfg.Op)+" skipped: placement already gone",
		slog.String("mirror_ulid", job.Target.ULID),
		slog.Int64("github_repo_id", job.GitHubRepoID),
	)
	recordJobSkipped(ctx, c.cfg.Op, skipReasonNotFound)
}

// disposePoison captures a permanently-unprocessable message to the DLQ and
// then Acks it — the only way to remove it from the WorkQueue. Term and
// MaxDeliver do NOT delete a message here; it would linger un-acked until
// StreamMaxAge (48h), pinning oldest_pending_age (COR-944). If the DLQ publish
// fails we Nak instead of Acking, so poison is never dropped without a captured
// copy.
func (c *Consumer) disposePoison(ctx context.Context, msg jetstream.Msg, reason string, cause error) {
	subject := dlqSubjectPrefix + string(c.cfg.Op) + "." + natsmsg.SubjectToken(reason)
	if dlqErr := natsmsg.DeadLetter(ctx, c.cfg.DLQ, subject, msg, reason); dlqErr != nil {
		slogutil.Error(ctx, "repo-ops dead-letter publish failed; naking (poison retained, not dropped)",
			slog.String("reason", reason),
			slog.String("subject", msg.Subject()),
			slog.String("dlq_error", dlqErr.Error()),
			slog.String("cause", cause.Error()),
		)
		if nakErr := msg.NakWithDelay(c.cfg.NakDelay); nakErr != nil {
			slogutil.Warn(ctx, "repo-ops nak after dead-letter failure failed", slog.String("error", nakErr.Error()))
		}
		return
	}
	recordJobTerminated(ctx, c.cfg.Op)
	if ackErr := msg.Ack(); ackErr != nil {
		slogutil.Warn(ctx, "repo-ops dead-letter ack failed", slog.String("error", ackErr.Error()))
	}
}

// terminate dead-letters a structurally broken message (bad subject/body/op)
// so it leaves the WorkQueue and is preserved for inspection/replay instead of
// redelivering or lingering.
func (c *Consumer) terminate(ctx context.Context, span trace.Span, msg jetstream.Msg, reason string, err error) {
	span.RecordError(err)
	span.SetStatus(otelcodes.Error, reason)
	span.SetAttributes(
		attribute.Bool("entire.error.permanent", true),
		attribute.Bool("entire.message.dead_lettered", true),
	)
	slogutil.Error(ctx, "repo-ops dead-lettering message",
		slog.String("reason", reason),
		slog.String("subject", msg.Subject()),
		slog.String("error", err.Error()),
	)
	c.disposePoison(ctx, msg, reason, err)
}

// recoverPanic disposes of a message whose processing panicked. It logs the
// recovered value plus a stack at ERROR and dead-letters the delivery so a
// poison event can't redeliver forever (nor linger un-acked on the WorkQueue).
// The Consume callback runs on the nats.go dispatch goroutine, which has no
// recover of its own, so without this a handler panic crashes the process.
func (c *Consumer) recoverPanic(ctx context.Context, span trace.Span, msg jetstream.Msg, recovered any) {
	err := fmt.Errorf("panic: %v", recovered)
	span.RecordError(err)
	span.SetStatus(otelcodes.Error, "panic")
	span.SetAttributes(
		attribute.Bool("entire.error.permanent", true),
		attribute.Bool("entire.message.dead_lettered", true),
	)
	slogutil.Error(ctx, "repo-ops recovered panic; dead-lettering message",
		slog.String("subject", msg.Subject()),
		slog.Any("panic", recovered),
		slog.String("stack", string(debug.Stack())),
	)
	c.disposePoison(ctx, msg, "panic", err)
}

func (c *Consumer) nak(ctx context.Context, span trace.Span, msg jetstream.Msg, err error) {
	span.RecordError(err)
	span.SetStatus(otelcodes.Error, "retriable")
	span.SetAttributes(attribute.Bool("entire.error.permanent", false))
	delay := c.nakDelay(deliveryCount(msg))
	slogutil.Warn(ctx, "repo-ops "+string(c.cfg.Op)+" failed; will retry",
		slog.String("subject", msg.Subject()),
		slog.Duration("retry_in", delay),
		slog.String("error", err.Error()),
	)
	recordJobNaked(ctx, c.cfg.Op)
	if nakErr := msg.NakWithDelay(delay); nakErr != nil {
		slogutil.Warn(ctx, "repo-ops nak failed", slog.String("error", nakErr.Error()))
	}
}

// nakDelay grows the redelivery delay geometrically with the delivery count,
// from NakDelay up to nakDelayMax. MaxDeliver is unlimited, so without a
// backoff any op stuck behind a regional/data-plane outage would redeliver
// every NakDelay for hours and hammer a store that is trying to recover. The
// backoff caps that churn while still retrying until the store recovers (or
// the job ages out at StreamMaxAge).
func (c *Consumer) nakDelay(numDelivered uint64) time.Duration {
	if numDelivered <= 1 {
		return c.cfg.NakDelay
	}
	shift := numDelivered - 1
	if shift >= 63 {
		return nakDelayMax
	}
	d := c.cfg.NakDelay << shift
	if d <= 0 { // overflow past the int64 Duration range
		return nakDelayMax
	}
	return min(d, nakDelayMax)
}

// deliveryCount is the message's NumDelivered (1 on first delivery), or 1 when
// metadata is unavailable (e.g. a non-JetStream test message) so the backoff
// degrades to the base NakDelay rather than panicking.
func deliveryCount(msg jetstream.Msg) uint64 {
	meta, err := msg.Metadata()
	if err != nil || meta == nil {
		return 1
	}
	return meta.NumDelivered
}

// TeardownIntent is the teardown consumer's desired-state gate (COR-506):
// StillMarkedForTeardown reports whether the placement row is still marked
// desired_state='deleted' — or already gone, which also proceeds (an earlier
// partial teardown left work to finish; every step is idempotent). A row
// present and ACTIVE means the durable intent was withdrawn after this job
// was published — a re-create's conditional clear, or the sweep clearing a
// superseded mark — so the job must skip: the mark, not the in-flight
// message, is what's authoritative at execution time. This is the gate that
// makes the enumerate→publish window race-free against Create: the clear and
// this read hit the same row, so a teardown executes only if the intent is
// live when the destructive action runs.
//
// *core/mirrorrepo.Service satisfies it; one row read on the global pool the
// regional core already holds.
type TeardownIntent interface {
	StillMarkedForTeardown(ctx context.Context, id model.RepoID) (bool, error)
}

// InstallationSuspension is the App-suspend suspend gate: InstallationSuspended
// reports whether the owning installation is CURRENTLY suspended (a
// github_installations row with suspended_at set). The suspend consumer
// consults it for jobs carrying SuspendGateInstallationSuspended: an
// installation.suspend blanking proceeds only while the App is still
// suspended, and skips if an unsuspend raced in and cleared suspended_at.
// *githubperms.Service satisfies it. A sibling gate of UpstreamFreshness
// because the App-suspend supersession signal is the installation's own state,
// not repo re-observation — see SuspendGate.
type InstallationSuspension interface {
	InstallationSuspended(ctx context.Context, installationID int64) (bool, error)
}

// UpstreamAttachment is the resume consumer's gate: RepoAttached reports
// whether githubRepoID is CURRENTLY attached to a live App installation —
// the installation row exists and is not suspended. An App suspension in
// the GitHub UI closes the gate until the unsuspend event clears it.
// Deliberately not observed-after — re-materializing grants is only safe
// against present attachment state, not against how the queue ordered
// events. *githubperms.Service satisfies it. A sibling of
// UpstreamFreshness rather than a second method on it so teardown/suspend
// wiring doesn't have to supply a gate it never consults.
type UpstreamAttachment interface {
	RepoAttached(ctx context.Context, githubRepoID int64) (bool, error)
}

// Config holds the consumer's required and tunable inputs. Op selects
// which executor + gate set is required: Teardowner/Freshness for teardown,
// Suspender/Freshness/Suspension/Attachment/Resumer for suspend (Freshness
// gates removal-driven jobs, Suspension gates App-suspend jobs, and
// Attachment/Resumer run the post-suspend re-check), Resumer/Attachment for
// resume. The zero Op means teardown for zero-value/test back-compat;
// production wiring always sets Op explicitly.
type Config struct {
	Op           Op
	Teardowner   Teardowner
	Suspender    Suspender
	Resumer      Resumer
	Conn         *nats.Conn
	DLQ          natsmsg.DLQPublisher
	Freshness    UpstreamFreshness
	Attachment   UpstreamAttachment
	Suspension   InstallationSuspension
	Intent       TeardownIntent
	Jurisdiction string
	DurableName  string
	AckWait      time.Duration
	MaxDeliver   int
	NakDelay     time.Duration
	FetchBatch   int
}

// Consumer drains repo.ops.v1.<jurisdiction>.*.<op> for one op and runs
// that op against each named mirror placement.
type Consumer struct {
	cfg           Config
	filterSubject string
}

// New validates the config and returns a Consumer. Fails fast on missing
// deps so wiring surfaces the problem at startup, not at first message.
func New(cfg Config) (*Consumer, error) {
	if cfg.Op == "" {
		cfg.Op = OpTeardown
	}
	switch cfg.Op {
	case OpTeardown:
		if cfg.Teardowner == nil {
			return nil, errors.New("repoops: Teardowner is required for op teardown")
		}
		if cfg.Freshness == nil {
			return nil, errors.New("repoops: Freshness is required (the last-writer-wins teardown gate)")
		}
		if cfg.Intent == nil {
			return nil, errors.New("repoops: Intent is required (the desired-state teardown gate, COR-506)")
		}
	case OpSuspend:
		if cfg.Suspender == nil {
			return nil, errors.New("repoops: Suspender is required for op suspend")
		}
