		// BOTH removal-driven jobs (Freshness gate) and App-suspend jobs
		// (Suspension gate), so a consumer missing it would Nak every App-suspend
		// forever. Fail fast at wiring instead.
		if cfg.Suspension == nil {
			return nil, errors.New("repoops: Suspension is required (the App-suspend installation-suspended gate)")
		}
