		// post-MarkSuspended attachment re-check that closes the TOCTOU
		// window against a racing re-add (see executeOp). Optional wiring
		// would let a deployment silently unwire the fix.
		if cfg.Attachment == nil {
			return nil, errors.New("repoops: Attachment is required (the post-suspend attachment re-check)")
		}
		if cfg.Resumer == nil {
			return nil, errors.New("repoops: Resumer is required (the post-suspend re-resume)")
		}
	case OpResume:

