	// mirrorDoneConsumer "" convention. A non-empty jurisdiction pins the
	// per-jurisdiction filter + durable that keep regional cores' consumers
	// non-overlapping on the shared central repo_ops_v1 stream (durable names
	// are unique per stream). The op token pins one op per durable — a
	// WorkQueue stream rejects consumers with overlapping filter subjects,
	// so teardown/suspend/resume each get their own. The cluster token is
	// always a wildcard: one regional core serves every cluster in its
	// jurisdiction.
	jurToken := cfg.Jurisdiction
	if jurToken == "" {
		jurToken = "*"
	}
	if cfg.DurableName == "" {
		scope := cfg.Jurisdiction
		if scope == "" {
			scope = "all"
		}
		cfg.DurableName = durableBase + "-" + string(cfg.Op) + "-" + scope
	}
	filter := SubjectPrefix + jurToken + ".*." + string(cfg.Op)
	return &Consumer{cfg: cfg, filterSubject: filter}, nil
}

// consumerConfig is the durable pull-consumer contract EnsureConsumer
// provisions and Run binds to. Extracted as a pure builder so the contract
// can be asserted without a live NATS (mirrors stream.go's applyContract).
//
// FilterSubject scopes this op's durable on the shared repo_ops_v1 WorkQueue
// stream. AckExplicitPolicy is mandatory — repo_ops_v1 is a WorkQueue stream,
// which only accepts explicit-ack consumers. AckWait and MaxDeliver are
// defaulted by New, so they are always populated here.
func (c *Consumer) consumerConfig() jetstream.ConsumerConfig {
	return jetstream.ConsumerConfig{
		Durable:       c.cfg.DurableName,
		FilterSubject: c.filterSubject,
		AckPolicy:     jetstream.AckExplicitPolicy,
		AckWait:       c.cfg.AckWait,
		MaxDeliver:    c.cfg.MaxDeliver,
	}
}

// jsConfig is the go-nuts/jsconsumer contract Run binds — the same durable,
// filter, AckExplicit policy, AckWait and MaxDeliver that consumerConfig (used by
// EnsureConsumer) pins, expressed for the shared supervise loop. Name carries the
// op so the three sibling consumers stay distinguishable in the scaffold's own
// log lines (it is a log label only, not the durable). MaxMessages mirrors the
// old FetchBatch (one in-flight delivery on this serial handler).
func (c *Consumer) jsConfig() jsconsumer.Config {
	return jsconsumer.Config{
		Name:          "repo-ops-" + string(c.cfg.Op),
		Stream:        StreamName,
		Durable:       c.cfg.DurableName,
		FilterSubject: c.filterSubject,
		AckWait:       c.cfg.AckWait,
		MaxDeliver:    c.cfg.MaxDeliver,
		MaxMessages:   c.cfg.FetchBatch,
	}
}

// EnsureConsumer pre-creates (and reconciles) the shared durable at boot. This
// is load-bearing, not a convenience: all of a region's core replicas share one
// durable on the central WorkQueue stream, so it must out-live any single pod,
// and calling it from wiring surfaces a create failure at startup rather than
// letting Run retry silently. CreateOrUpdateConsumer creates it explicitly and
// it persists server-side — a ConsumeContext.Stop()/process exit never removes
// it, and Run's own create-or-update (via natsx) reconciles it thereafter.
//
// Idempotent and safe for every replica to call on boot: create-or-update
// returns the existing consumer when the config matches and reconciles a
// drifted tunable (AckWait / MaxDeliver) in place. Call after EnsureStream —
// the consumer can't exist before its stream.
func (c *Consumer) EnsureConsumer(ctx context.Context) error {
	js, err := jetstream.New(c.cfg.Conn)
	if err != nil {
		return fmt.Errorf("jetstream client: %w", err)
	}
	if _, err := js.CreateOrUpdateConsumer(ctx, StreamName, c.consumerConfig()); err != nil {
		return fmt.Errorf("durable %q on stream %q: %w", c.cfg.DurableName, StreamName, err)
	}
	return nil
}

// Run supervises the shared durable until ctx is cancelled. Per-message errors
// are disposed via Ack/Nak/Term inside handleMessage, never propagated. The
// create-or-update / consume / reconnect-with-backoff mechanism lives in natsx;
// the op + filter are logged so the three sibling consumers (teardown / suspend
// / resume) that share this loop stay distinguishable.
func (c *Consumer) Run(ctx context.Context) {
	if err := jsconsumer.Run(ctx, c.cfg.Conn, c.jsConfig(), func(msg jetstream.Msg) {
		c.handleMessage(ctx, msg)
	}); err != nil {
		slogutil.Error(ctx, "repo-ops consumer stopped",
			slog.String("op", string(c.cfg.Op)), slog.String("error", err.Error()))
	}
}

// handleMessage processes one delivery: parse subject + body, run the
// op, dispose. A structurally broken message (bad subject/body, or an op
// this consumer doesn't run) Terms — replay can't fix it. An op failure
// Naks; every executor is idempotent so redelivery converges.
func (c *Consumer) handleMessage(ctx context.Context, msg jetstream.Msg) {
	ctx = natsmsg.ExtractHeader(ctx, msg.Headers())
	ctx, span := otel.Tracer(consumerTracerName).Start(ctx, fmt.Sprintf("repo.ops.%s.consume", c.cfg.Op),
		trace.WithSpanKind(trace.SpanKindConsumer),
		trace.WithAttributes(
			attribute.String("messaging.system", "nats"),
			attribute.String("messaging.operation.type", "receive"),
			attribute.String("messaging.destination.name", msg.Subject()),
		),
	)

package permswebhook

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"runtime/debug"
	"time"

	"github.com/entireio/go-nuts/jsconsumer"
	"github.com/entireio/go-nuts/natsmsg"
	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	otelcodes "go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"entire.io/core/githubperms"
	"entire.io/slogutil"
)

const (
	// DurableName is the JetStream durable consumer name. One per cluster —
	// the metadata mirror is global, so this never fans out by
	// jurisdiction/region. Changing it orphans the existing durable and
	// re-reads from scratch, so treat it as load-bearing.
	DurableName = "entirecore-webhook-meta"

	defaultAckWait = 2 * time.Minute
	// defaultMaxDeliver is unlimited (-1) on purpose, same rationale as
	// repoops: the metadata writes are idempotent and observedAt-gated, and
	// the suspend/teardown fan-outs this consumer drives are NOT
	// re-derivable — GitHub never resends the webhook. A finite cap would
	// let a ~1-minute repo_ops publish outage exhaust the redeliveries
	// server-side (no client signal) and permanently drop the fan-out,
	// leaving live grants with their metadata intact and nothing left to
	// redeliver. Poison payloads Term via permanent(), so unlimited retry
	// only rides out transient failures; nakDelay backs the retries off.
	defaultMaxDeliver = -1
	defaultNakDelay   = 5 * time.Second
	// defaultFetchBatch caps in-flight deliveries at one at a time (via
	// PullMaxMessages). In steady state the jetstream client requests the next
	// delivery only after the handler returns (checkPending runs post-handler,
	// and the default threshold ceil(1/2)=1 never refills while one is
	// outstanding), so the serial handler — which heartbeats a long teardown
	// fan-out via KeepInProgress — has no un-heartbeated sibling aging toward
	// AckWait. The one exception is a reconnect mid-apply, whose re-pull can
	// buffer a single delivery behind the running one; bounded to one, and
	// redelivery is idempotent (observedAt-gated, MaxDeliver -1) so it re-applies
	// harmlessly.
	defaultFetchBatch = 1

	// defaultRetryBackoffMax caps the geometric NAK backoff in nakDelay (the
	// reconnect-backoff role it also played under natsx is now owned by
	// go-nuts/jsconsumer). MaxDeliver is unlimited, so this ceiling stops a
	// message stuck behind a persistent transient failure from hammering a
	// recovering store.
	defaultRetryBackoffMax = 30 * time.Second

	// defaultInactiveThreshold has the SERVER reap the durable after 72h
	// without a pull request. webhooks_github_v1 is interest-retention: a
	// durable nobody pulls (a retired deployment, or the old durable left
	// behind by a rename — see the DurableName warning above) pins every
	// subsequent delivery for ALL of the stream's consumers until its
	// maxAge/maxBytes wall, which stalled the whole mirror pipeline on
	// 2026-06-01. 72h sits under the stream's 96h maxAge.
	//
	// Tension with defaultMaxDeliver = -1, acknowledged: this consumer's
	// events are not re-derivable, and a deployment down for more than 72h
	// loses the durable and with it the events published until it returns.
	// That is a disaster-recovery scenario (entire-core-global absent for
	// three days); the perms reconciler CronJob is the authoritative
	// backstop that re-derives grant state from SpiceDB + GitHub, and an
	// unblocked webhook pipeline for every other consumer is worth more
	// than a >72h-stale cursor.
	defaultInactiveThreshold = 72 * time.Hour
)

const tracerName = "permswebhook"

// eventApplier turns a decoded webhook into DB writes. The metadata path
// (applier) and the read-model path (permsApplier) both satisfy it, so the
// Consumer's handle/ack loop is shared between the two durables.
type eventApplier interface {
	apply(ctx context.Context, event, deliveryID string, observedAt time.Time, body []byte) error
}

// Config holds the consumer's required and tunable inputs. Zero values
// fall back to the package-level defaults.
type Config struct {
	Service     *githubperms.Service
	Conn        *nats.Conn
	DurableName string
	// Applier and FilterSubjects select what this consumer does. Zero
	// values default to the metadata path (the applier built from Service,
	// filtering the three installation/repo subjects) so existing callers
	// are unchanged; the read-model consumer passes its own.
	Applier        eventApplier
	FilterSubjects []string
	// Visibility propagates repository public/private changes to SpiceDB on
	// every repository upsert (COR-758). Optional: nil disables propagation
	// (tests / deployments that don't have SpiceDB wired).
	Visibility visibilityPropagator
	// Ops fans repo-operation jobs out around the metadata writes:
	// teardown on the permanent delete, suspend on the reversible
	// offline events, resume on re-attach. Optional: nil leaves the
	// consumer metadata-only, used in deployments without repo-ops
	// wiring. Only consulted for the default metadata applier (when
	// Applier is nil); the read-model applier publishes no ops.
	Ops opsFanout
	// Sweep publishes one immediate perms-sweep job after a successful
	// installation.created / installation_repositories.added upsert, so a
	// fresh install's collaborator snapshots start within seconds instead of
	// at the next hourly enumerator tick. Optional and best-effort: nil (or
	// a publish failure) leaves the hourly enumerator as the only trigger.
	// Only consulted for the default metadata applier.
	Sweep             sweepPublisher
	AckWait           time.Duration
	MaxDeliver        int
	NakDelay          time.Duration
	FetchBatch        int
	RetryBackoffMx    time.Duration
	InactiveThreshold time.Duration
}

// Consumer is the long-running JetStream subscriber that drains a filtered
// set of webhook event subjects off webhooks_github_v1 and applies them.
type Consumer struct {
	cfg     Config
	applier eventApplier
}

// New validates the config and returns a Consumer. Fails fast if required
// deps are nil so the wiring layer surfaces the problem at startup rather
// than at first message.
func New(cfg Config) (*Consumer, error) {
	if cfg.Conn == nil {
		return nil, errors.New("permswebhook: Conn is required")
	}
	if cfg.Applier == nil {
		// Default: the installation/repo metadata path. It needs the
		// metadata Service.
		if cfg.Service == nil {
			return nil, errors.New("permswebhook: Service is required for the default metadata applier")
		}
		cfg.Applier = &applier{svc: cfg.Service, visibility: cfg.Visibility, ops: cfg.Ops, sweep: cfg.Sweep}
	}
	if len(cfg.FilterSubjects) == 0 {
		cfg.FilterSubjects = filterSubjects
	}
	if cfg.DurableName == "" {
		cfg.DurableName = DurableName
	}
	if cfg.AckWait == 0 {
		cfg.AckWait = defaultAckWait
	}
	if cfg.MaxDeliver == 0 {
		cfg.MaxDeliver = defaultMaxDeliver
	}
	if cfg.NakDelay == 0 {
		cfg.NakDelay = defaultNakDelay
	}
	if cfg.FetchBatch == 0 {
		cfg.FetchBatch = defaultFetchBatch
	}
	if cfg.RetryBackoffMx == 0 {
		cfg.RetryBackoffMx = defaultRetryBackoffMax
	}
	if cfg.InactiveThreshold == 0 {
		cfg.InactiveThreshold = defaultInactiveThreshold
	}
	return &Consumer{cfg: cfg, applier: cfg.Applier}, nil
}

// consumerConfig is the durable pull-consumer contract Run create-or-updates and
// consumes from. webhooks_github_v1 is operator-owned; this consumer binds its
// own durable + multi-filter on it. InactiveThreshold rides the create-or-update
// config, which applies the full config on every call, so the reap window is
// reconciled in place with no separate step.
func (c *Consumer) consumerConfig() jsconsumer.Config {
	return jsconsumer.Config{
		Name:              "webhook-perms",
		Stream:            StreamName,
		Durable:           c.cfg.DurableName,
		FilterSubjects:    c.cfg.FilterSubjects,
		AckWait:           c.cfg.AckWait,
		MaxDeliver:        c.cfg.MaxDeliver,
		InactiveThreshold: c.cfg.InactiveThreshold,
		MaxMessages:       c.cfg.FetchBatch,
	}
}

// Run supervises the webhook-perms durable until ctx is cancelled. The
// create-or-update / consume / reconnect-with-backoff mechanism lives in
// go-nuts/jsconsumer; handling and disposition stay here (see handleMessage).
// InactiveThreshold rides consumerConfig, which the runner re-applies on every
// create-or-update, so the reap window is reconciled in place with no separate
// step. jsconsumer.Run blocks until ctx is cancelled.
func (c *Consumer) Run(ctx context.Context) {
	if err := jsconsumer.Run(ctx, c.cfg.Conn, c.consumerConfig(), func(msg jetstream.Msg) {
		c.handleMessage(ctx, msg)
	}); err != nil {
		slogutil.Error(ctx, "webhook-perms consumer stopped", slog.String("error", err.Error()))
	}
}

// handleMessage processes one delivery and applies a disposition
// (Ack / Nak / Term). Span and log records cover every outcome.
func (c *Consumer) handleMessage(ctx context.Context, msg jetstream.Msg) {
	ctx = natsmsg.ExtractHeader(ctx, msg.Headers())
	ctx, span := otel.Tracer(tracerName).Start(ctx, "mirror.perms.webhook.consume",
		trace.WithSpanKind(trace.SpanKindConsumer),
		trace.WithAttributes(
			attribute.String("messaging.system", "nats"),
			attribute.String("messaging.operation.type", "receive"),
			attribute.String("messaging.destination.name", msg.Subject()),
		),
	)
	defer span.End()

	// Poison-message guard: a panic while decoding or applying one delivery must
	// not kill the consumer goroutine. A redelivering poison event (e.g. the
	// COR-730 membership event that nil-derefed a.mirrors) would otherwise crash
	// entire-core on every restart. Recover, record the stack at ERROR, and
	// Term the delivery so it does not redeliver forever. Both the metadata and
	// read-model durables share this loop, so both are protected.
	defer func() {
		if r := recover(); r != nil {
			c.recoverPanic(ctx, span, msg, r)
		}
	}()

	if meta, err := msg.Metadata(); err == nil {
		span.SetAttributes(
			attribute.Int64("messaging.nats.sequence", natsmsg.ClampToInt64(meta.Sequence.Stream)),
			attribute.Int64("messaging.nats.delivery_count", natsmsg.ClampToInt64(meta.NumDelivered)),
		)
	}

	fw, err := unmarshalEnvelope(msg.Data())
	if err != nil {
		c.terminate(ctx, span, msg, "bad envelope", err)
		return
	}
	span.SetAttributes(
		attribute.String("entire.webhook.event", fw.Event),
		attribute.String("entire.webhook.delivery_id", fw.DeliveryID),
	)

	slogutil.Info(ctx, "webhook-perms consume",
		slog.String("subject", msg.Subject()),
		slog.String("event", fw.Event),
		slog.String("delivery_id", fw.DeliveryID),
	)

	// Keep the delivery alive while apply runs: a whole-installation
	// teardown fan-out publishes one job per placement and can legitimately
	// outlive AckWait on a large installation — without the heartbeat the
	// broker would redeliver the SAME event into a second concurrent
	// fan-out, and an apply that consistently exceeds AckWait would
	// redeliver forever without ever Acking. The extension is capped
	// (natsmsg.KeepInProgress) so a truly wedged apply still falls back to
	// AckWait redelivery on a healthy replica. Stopped (idempotently)
	// before every terminal disposition; the deferred stop covers the
	// panic path, where recoverPanic Terms.
	stopHeartbeat := natsmsg.KeepInProgress(func() error { return msg.InProgress() }, c.cfg.AckWait)
	defer stopHeartbeat()

	applyErr := c.applier.apply(ctx, fw.Event, fw.DeliveryID, fw.ReceivedAt, fw.Body)
	stopHeartbeat()
	if applyErr != nil {
		c.disposeError(ctx, span, msg, applyErr)
		return
	}
	if err := msg.Ack(); err != nil {
		slogutil.Warn(ctx, "webhook-perms ack failed", slog.String("error", err.Error()))
	}
}

// terminate logs + spans the failure and Term()s the message so it won't
// be redelivered. Reserved for structurally broken inputs — no amount of
// retrying will make them apply.
func (c *Consumer) terminate(ctx context.Context, span trace.Span, msg jetstream.Msg, reason string, err error) {
	span.RecordError(err)
	span.SetStatus(otelcodes.Error, reason)
	span.SetAttributes(
		attribute.Bool("entire.error.permanent", true),
		attribute.Bool("entire.message.terminated", true),
	)
	slogutil.Error(ctx, "webhook-perms terminating message",
		slog.String("reason", reason),
		slog.String("subject", msg.Subject()),
		slog.String("error", err.Error()),
	)
	if termErr := msg.Term(); termErr != nil {
		slogutil.Warn(ctx, "webhook-perms term failed", slog.String("error", termErr.Error()))
	}
}

// recoverPanic disposes of a message whose processing panicked. It logs the
// recovered value plus a stack at ERROR and Term()s the delivery so a poison
// event can't redeliver forever (one bad event => one ERROR log, not a global
// outage). The panic is treated as permanent — a nil-deref or bad-shape crash
// won't fix itself on replay.
func (c *Consumer) recoverPanic(ctx context.Context, span trace.Span, msg jetstream.Msg, recovered any) {
	err := fmt.Errorf("panic: %v", recovered)
	span.RecordError(err)
	span.SetStatus(otelcodes.Error, "panic")
	span.SetAttributes(
		attribute.Bool("entire.error.permanent", true),
		attribute.Bool("entire.message.terminated", true),
	)
	slogutil.Error(ctx, "webhook-perms recovered panic; terminating message",
		slog.String("subject", msg.Subject()),
		slog.Any("panic", recovered),
		slog.String("stack", string(debug.Stack())),
	)
	if termErr := msg.Term(); termErr != nil {
		slogutil.Warn(ctx, "webhook-perms term after panic failed", slog.String("error", termErr.Error()))
	}
}

// disposeError chooses Term vs Nak for an apply-time failure. Permanent
// errors (malformed body) Term so they don't burn the redelivery budget;
// transient errors (DB blip) Nak with delay so they reapply after backoff.
func (c *Consumer) disposeError(ctx context.Context, span trace.Span, msg jetstream.Msg, err error) {
	span.RecordError(err)
	if isPermanent(err) {
		span.SetStatus(otelcodes.Error, "permanent")
		span.SetAttributes(
			attribute.Bool("entire.error.permanent", true),
			attribute.Bool("entire.message.terminated", true),
		)
		slogutil.Error(ctx, "webhook-perms apply permanent failure",
			slog.String("subject", msg.Subject()),
			slog.String("error", err.Error()),
		)
		if termErr := msg.Term(); termErr != nil {
			slogutil.Warn(ctx, "webhook-perms term failed", slog.String("error", termErr.Error()))
		}
		return
	}
	span.SetStatus(otelcodes.Error, "retriable")
	span.SetAttributes(attribute.Bool("entire.error.permanent", false))
	delay := c.nakDelay(deliveryCount(msg))
	slogutil.Warn(ctx, "webhook-perms apply retriable failure",
		slog.String("subject", msg.Subject()),
		slog.Duration("retry_in", delay),
		slog.String("error", err.Error()),
	)
	if nakErr := msg.NakWithDelay(delay); nakErr != nil {
		slogutil.Warn(ctx, "webhook-perms nak failed", slog.String("error", nakErr.Error()))
	}
}

// nakDelay grows the redelivery delay geometrically with the delivery count,
// from NakDelay up to RetryBackoffMx — mirroring repoops' backoff. MaxDeliver
// is unlimited, so without it a message stuck behind a persistent transient
// failure would redeliver every NakDelay for hours and hammer a store that is
// trying to recover.
func (c *Consumer) nakDelay(numDelivered uint64) time.Duration {
	if numDelivered <= 1 {
		return c.cfg.NakDelay
	}
	shift := numDelivered - 1
	if shift >= 63 {
		return c.cfg.RetryBackoffMx
	}
	d := c.cfg.NakDelay << shift
	if d <= 0 { // overflow past the int64 Duration range
		return c.cfg.RetryBackoffMx
	}
	return min(d, c.cfg.RetryBackoffMx)
}

// deliveryCount is the message's NumDelivered (1 on first delivery), or 1 when
// metadata is unavailable (e.g. a non-JetStream test message) so the backoff
// degrades to the base NakDelay rather than panicking.
func deliveryCount(msg jetstream.Msg) uint64 {
	meta, err := msg.Metadata()
	if err != nil || meta == nil {
		return 1
	}
	return meta.NumDelivered
}

// permanentError marks an error as non-retriable so the disposition
// chooses Term instead of Nak.
type permanentError struct{ err error }

func (e *permanentError) Error() string { return e.err.Error() }
func (e *permanentError) Unwrap() error { return e.err }

func permanent(err error) error { return &permanentError{err: err} }

func isPermanent(err error) bool {
	var pe *permanentError
	return errors.As(err, &pe)
}

package repoops

import (
	"context"
	"fmt"
	"log/slog"
	"time"

	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	otelcodes "go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/propagation"
	"go.opentelemetry.io/otel/trace"

	"entire.io/slogutil"
)

const tracerName = "entire.io/internal/entirecore/repoops"

// NatsMsgIDHeader is the JetStream dedup header. A re-published job for
// the same op, placement, and observation within StreamDuplicatesWindow
// collapses server-side, so the producer can retry one webhook without
// enqueuing it twice. Distinct observations must not collapse: an upstream
// can be removed, re-added, then removed again inside the duplicate
// window, and the older job may legitimately skip via the
// last-writer-wins gate.
const NatsMsgIDHeader = "Nats-Msg-Id"

// JetStreamPublisher is the slice of nats.JetStreamContext the Publisher
// needs, pulled out so tests can stub publish without a live JetStream.
type JetStreamPublisher interface {
	PublishMsg(m *nats.Msg, opts ...nats.PubOpt) (*nats.PubAck, error)
}

// Publisher publishes repo-operation jobs onto repo_ops_v1. Used by
// entire-core-global's webhook consumer to fan teardowns, App-suspends, and
// resumes out to the region that owns each placement.
type Publisher struct {
	js JetStreamPublisher
}

// NewPublisher binds a Publisher to a JetStream context.
func NewPublisher(js JetStreamPublisher) *Publisher {
	return &Publisher{js: js}
}

// PublishTeardown emits one teardown job for a single placement.
// Idempotent on the op + target ULID + observedAt via the Nats-Msg-Id
// dedup header. OTel trace context rides the NATS headers so the regional
// consumer's span parents to this publish.
//
// observedAt is the removal webhook's observation time; the consumer uses
// it as the last-writer-wins threshold for its skip-if-re-added gate.
func (p *Publisher) PublishTeardown(ctx context.Context, placement Placement, target Target, githubRepoID int64, observedAt time.Time) error {
	return p.publishOp(ctx, OpTeardown, SuspendGateRemoval, placement, target, githubRepoID, 0, observedAt)
}

// PublishAppSuspend emits one App-suspend job (installation.suspend) for a
// single placement. It stamps the installation-suspended gate and carries
// installationID, so the consumer gates it on the owning installation still
// being suspended rather than on repo re-observation. observedAt only feeds
// the dedup key here; the gate is current installation state, not
// observed-after. (The removal-driven PublishSuspend is gone — every
// GitHub-side removal tears down instead, COR-454.)
func (p *Publisher) PublishAppSuspend(ctx context.Context, placement Placement, target Target, githubRepoID, installationID int64, observedAt time.Time) error {
	return p.publishOp(ctx, OpSuspend, SuspendGateInstallationSuspended, placement, target, githubRepoID, installationID, observedAt)
}

// PublishResume emits one resume job for a single placement (App
// unsuspend). observedAt is the webhook's observation time; the resume
// consumer gates on CURRENT attachment rather than observed-after, so here
// it only feeds the dedup key.
func (p *Publisher) PublishResume(ctx context.Context, placement Placement, target Target, githubRepoID int64, observedAt time.Time) error {
	return p.publishOp(ctx, OpResume, SuspendGateRemoval, placement, target, githubRepoID, 0, observedAt)
}

func (p *Publisher) publishOp(ctx context.Context, op Op, gate SuspendGate, placement Placement, target Target, githubRepoID, installationID int64, observedAt time.Time) error {
	parsed := ParsedSubject{Placement: placement, Op: op}
	subject := Subject(parsed)
	job := Job{Target: target, GitHubRepoID: githubRepoID, ObservedAt: observedAt, SuspendGate: gate, InstallationID: installationID}

	ctx, span := otel.Tracer(tracerName).Start(ctx, "repo.ops.publish",
		trace.WithSpanKind(trace.SpanKindProducer),
		trace.WithAttributes(
			attribute.String("messaging.system", "nats"),
			attribute.String("messaging.operation.type", "publish"),
			attribute.String("messaging.destination.name", subject),
			attribute.String("entire.operation", string(parsed.Op)),
			attribute.String("entire.target_jurisdiction", placement.Jurisdiction),
			attribute.String("entire.target_cluster_slug", placement.ClusterSlug),
			attribute.String("entire.target_ulid", target.ULID),
		),
	)
	defer span.End()

	data, err := Marshal(job)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "marshal repo-ops job")
		return fmt.Errorf("marshal repo-ops job: %w", err)
	}

	// Dedup key is op + target ULID + observation time. A producer retry of
	// the same webhook collapses, but a later removal of the same placement
	// after a re-add must enqueue separately; otherwise the stale first job
	// can skip via the freshness gate and lose the real teardown/suspend.
	// The op token keeps distinct ops for the same observation from
	// collapsing into one job.
	msgID := fmt.Sprintf("%s/%s/%s", parsed.Op, target.ULID, observedAt.UTC().Format(time.RFC3339Nano))
	msg := &nats.Msg{Subject: subject, Data: data, Header: nats.Header{}}
	msg.Header.Set(NatsMsgIDHeader, msgID)
	otel.GetTextMapPropagator().Inject(ctx, headerCarrier(msg.Header))
	span.SetAttributes(attribute.String("messaging.message.id", msgID))

	ack, err := p.js.PublishMsg(msg, nats.Context(ctx))
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "nats publish")
		return fmt.Errorf("publish repo-ops %s: %w", op, err)
	}
	span.SetAttributes(attribute.Bool("messaging.nats.duplicate", ack.Duplicate))
	slogutil.Info(ctx, "published repo-ops job",
		slog.String("op", string(op)),
		slog.String("subject", subject),
		slog.String("msg_id", msgID),
		slog.String("target_ulid", target.ULID),
		slog.Bool("duplicate", ack.Duplicate),
	)
	return nil
}

// headerCarrier adapts nats.Header to the OTel TextMapCarrier contract.
type headerCarrier nats.Header

func (c headerCarrier) Get(key string) string {
	v := nats.Header(c).Values(key)
	if len(v) == 0 {
		return ""
	}
	return v[0]
}
func (c headerCarrier) Set(key, value string) { nats.Header(c).Set(key, value) }
func (c headerCarrier) Keys() []string {
	keys := make([]string, 0, len(c))
	for k := range c {
		keys = append(keys, k)
	}
	return keys
}

var _ propagation.TextMapCarrier = headerCarrier(nil)

package gitjobs

import (
	"context"
	"fmt"
	"log/slog"

	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	otelcodes "go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/propagation"
	"go.opentelemetry.io/otel/trace"

	"entire.io/slogutil"
)

const tracerName = "entire.io/core/mirrorrepo/gitjobs"

// NatsMsgIDHeader is the JetStream deduplication header. Reuse across
// retries within the StreamDuplicatesWindow collapse to a single
// stored message server-side. Same constant string mirror-pipeline
// uses; spelt out here to avoid pulling in nats.go's internal const.
const NatsMsgIDHeader = "Nats-Msg-Id"

// JetStreamPublisher is the slice of nats.JetStreamContext the
// Publisher needs. Pulled out as an interface so tests can stub
// publish without a live JetStream.
type JetStreamPublisher interface {
	PublishMsg(m *nats.Msg, opts ...nats.PubOpt) (*nats.PubAck, error)
}

// Publisher publishes git-sync jobs onto the canonical mirror_git_v1
// stream. mirror-pipeline owns the stream creation; entire-core only
// publishes. One Publisher targets one JetStream: a regional core is
// co-located with the single cluster it serves, so its git jobs always
// go to that cluster's NATS (configured via ENTIRE_MIRROR_GIT_NATS_URL).
type Publisher struct {
	js JetStreamPublisher
}

// NewPublisher binds a Publisher to a JetStream context.
func NewPublisher(js JetStreamPublisher) *Publisher {
	return &Publisher{js: js}
}

// PublishSyncRepo emits a single sync_repo job. Idempotent on
// (placement, source, target) via the Nats-Msg-Id dedup header — a
// retry within StreamDuplicatesWindow collapses server-side, so the
// caller doesn't have to coordinate. OTel trace context rides the
// NATS headers so the worker's span parents to this publish.
//
// A nil Publisher receiver or nil js panics on call: callers MUST
// wire a publisher, and serve-mode boot enforces it (see
// buildGitJobsPublisher). Silently treating nil as "skip the publish"
// is what stranded EU mirrors in provisioning state.
func (p *Publisher) PublishSyncRepo(ctx context.Context, placement Placement, source Source, target Target) error {
	parsed := ParsedSubject{
		Placement:  placement,
		SourceKind: SourceKindGithub,
		Op:         OpSyncRepo,
	}
	job := Job{Source: source, Target: target}
	subject := Subject(parsed)

	spanAttrs := []attribute.KeyValue{
		attribute.String("messaging.system", "nats"),
		attribute.String("messaging.operation.type", "publish"),
		attribute.String("messaging.destination.name", subject),
		attribute.String("entire.operation", string(parsed.Op)),
		attribute.String("entire.source_kind", string(parsed.SourceKind)),
		attribute.String("entire.target_jurisdiction", placement.Jurisdiction),
		attribute.String("entire.target_cluster_id", placement.ClusterID),
		attribute.String("entire.source_owner", source.Owner),
		attribute.String("entire.source_repo", source.Repo),
		attribute.String("entire.target_ulid", target.ULID),
	}

	ctx, span := otel.Tracer(tracerName).Start(ctx, "mirror.git.publish",
		trace.WithSpanKind(trace.SpanKindProducer),
		trace.WithAttributes(spanAttrs...),
	)
	defer span.End()

	data, err := Marshal(job)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "marshal git job")
		return fmt.Errorf("marshal git job: %w", err)
	}

	// Msg-ID dedup key: same shape mirror-pipeline's resync-scheduler
	// uses (op/source-kind/owner/repo/ulid). A retry of the *same*
	// create-mirror call collapses; a separate placement on the same
	// upstream gets a distinct key because target.ULID differs.
	msgID := fmt.Sprintf("%s/%s/%s/%s/%s",
		parsed.Op, parsed.SourceKind,
		source.Owner, source.Repo, target.ULID,
	)
	msg := &nats.Msg{
		Subject: subject,
		Data:    data,
		Header:  nats.Header{},
	}
	msg.Header.Set(NatsMsgIDHeader, msgID)
	otel.GetTextMapPropagator().Inject(ctx, HeaderCarrier(msg.Header))
	span.SetAttributes(attribute.String("messaging.message.id", msgID))

	ack, err := p.js.PublishMsg(msg, nats.Context(ctx))
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "nats publish")
		return fmt.Errorf("publish git mirror job: %w", err)
	}

	span.SetAttributes(
		attribute.Int64("messaging.nats.sequence", int64(ack.Sequence)), //nolint:gosec // ack.Sequence is uint64; values that overflow int64 are out of scope
		attribute.Bool("messaging.nats.duplicate", ack.Duplicate),
	)
	slogutil.Info(ctx, "published git mirror sync_repo",
		slog.String("subject", subject),
		slog.String("msg_id", msgID),
		slog.String("source_owner", source.Owner),
		slog.String("source_repo", source.Repo),
		slog.String("target_ulid", target.ULID),
		slog.Bool("duplicate", ack.Duplicate),
	)
	return nil
}

// HeaderCarrier adapts nats.Header to the OTel TextMapCarrier contract so
// trace context propagates over JetStream. Exported so other entire-core NATS
// producers (e.g. the mirror-resync publisher) reuse the one adapter instead of
// re-copying it.
type HeaderCarrier nats.Header

func (c HeaderCarrier) Get(key string) string {
	v := nats.Header(c).Values(key)
	if len(v) == 0 {
		return ""
	}
	return v[0]
}
func (c HeaderCarrier) Set(key, value string) { nats.Header(c).Set(key, value) }
func (c HeaderCarrier) Keys() []string {
	keys := make([]string, 0, len(c))
	for k := range c {
		keys = append(keys, k)
	}
	return keys
}

var _ propagation.TextMapCarrier = HeaderCarrier(nil)

package entirecore

import (
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"time"

	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	otelcodes "go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"entire.io/core/api"
	"entire.io/core/mirrorrepo/gitjobs"
	"entire.io/core/model"
	"entire.io/internal/entirecore/permswebhook"
	"entire.io/slogutil"
)

const resyncTracerName = "entire.io/internal/entirecore/resync"

// resyncWebhookPublisher publishes a synthetic GitHub "push" ForwardedWebhook
// onto the central webhooks_github_v1 JetStream (ENTIRE_NATS_URL, central US),
// which mirror-pipeline's existing fanout consumes to resync a repo (ENT-1172).
// It reuses the permswebhook envelope + subject constants (structurally
// identical to mirror-pipeline/pkg/webhookevents.ForwardedWebhook) and the
// gitjobs dedup-header constant, so this producer and the consumer can't drift.
//
// It publishes to the CENTRAL stream (cfg.NatsURL), NOT the in-cell mirror
// stream the gitJobsPublisher targets (cfg.MirrorGitNatsURL): the resync must
// land where cmd/fanout consumes, which is the central webhooks_github_v1.
type resyncWebhookPublisher struct {
	js gitjobs.JetStreamPublisher
}

var _ api.ResyncPublisher = (*resyncWebhookPublisher)(nil)

func newResyncWebhookPublisher(js gitjobs.JetStreamPublisher) *resyncWebhookPublisher {
	return &resyncWebhookPublisher{js: js}
}

// resyncPushBody is the minimal GitHub push payload mirror-pipeline's fanout
// reads: only repository.full_name and installation.id (see
// ../mirror-pipeline/cmd/fanout/payloads.go). No ref/commits/after — the worker
// syncs AllRefs regardless. The installation id is required so a private
// checkpoints repo can mint an installation token.
type resyncPushBody struct {
	Repository struct {
		FullName string `json:"full_name"`
	} `json:"repository"`
	Installation struct {
		ID int64 `json:"id"`
	} `json:"installation"`
}

// PublishResync builds and publishes the synthetic push webhook for repoID.
//
// DeliveryID buckets on the minute so the stream's ~5-min dedup window collapses
// a burst of resyncs from one busy repo into a single message (the free dedup
// win, not the deferred de-dup subsystem). OTel trace context rides the NATS
// headers so the fanout worker's span parents to this publish.
func (p *resyncWebhookPublisher) PublishResync(ctx context.Context, repoID model.RepoID, fullName string, installationID int64) error {
	var body resyncPushBody
	body.Repository.FullName = fullName
	body.Installation.ID = installationID
	rawBody, err := json.Marshal(body)
	if err != nil {
		return fmt.Errorf("marshal resync push body: %w", err)
	}

	deliveryID := fmt.Sprintf("resync-%s-%d", repoID, time.Now().Unix()/60)
	env := permswebhook.ForwardedWebhook{
		DeliveryID: deliveryID,
		Event:      "push",
		Body:       rawBody,
		ReceivedAt: time.Now(),
	}
	data, err := json.Marshal(env)
	if err != nil {
		return fmt.Errorf("marshal forwarded webhook: %w", err)
	}

	subject := permswebhook.SubjectPrefix + "push"
	ctx, span := otel.Tracer(resyncTracerName).Start(ctx, "mirror.resync.publish",
		trace.WithSpanKind(trace.SpanKindProducer),
		trace.WithAttributes(
			attribute.String("messaging.system", "nats"),
			attribute.String("messaging.operation.type", "publish"),
			attribute.String("messaging.destination.name", subject),
			attribute.String("entire.repo_id", repoID.String()),
			attribute.String("entire.source_full_name", fullName),
		),
	)
	defer span.End()

	msg := &nats.Msg{Subject: subject, Data: data, Header: nats.Header{}}
	msg.Header.Set(gitjobs.NatsMsgIDHeader, deliveryID)
	otel.GetTextMapPropagator().Inject(ctx, gitjobs.HeaderCarrier(msg.Header))
	span.SetAttributes(attribute.String("messaging.message.id", deliveryID))

	ack, err := p.js.PublishMsg(msg, nats.Context(ctx))
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "nats publish")
		return fmt.Errorf("publish resync webhook: %w", err)
	}

	span.SetAttributes(
		attribute.Int64("messaging.nats.sequence", int64(ack.Sequence)), //nolint:gosec // ack.Sequence is uint64; values that overflow int64 are out of scope
		attribute.Bool("messaging.nats.duplicate", ack.Duplicate),
	)
	slogutil.Info(ctx, "published mirror resync webhook",
		slog.String("subject", subject),
		slog.String("delivery_id", deliveryID),
		slog.String("repo_id", repoID.String()),
		slog.String("full_name", fullName),
		slog.Int64("installation_id", installationID),
		slog.Bool("duplicate", ack.Duplicate),
	)
	return nil
}

// buildResyncPublisher returns a resync publisher bound to the CENTRAL NATS
// (cfg.NatsURL, where cmd/fanout consumes webhooks_github_v1) plus a cleanup
// that closes the connection. Unlike buildGitJobsPublisher — which requires
// NATS and fails boot — this degrades to a disabled (nil) publisher when
// cfg.NatsURL is unset, so a config without central NATS still boots; resync
// then returns ErrResyncUnavailable (503). In regional/standalone cfg.NatsURL
// is set in practice (the gitjobs publisher already requires a NATS URL).
func buildResyncPublisher(ctx context.Context, cfg Config) (*resyncWebhookPublisher, func(), error) {
	if cfg.NatsURL == "" {
		slogutil.Info(ctx, "mirror resync publisher disabled: ENTIRE_NATS_URL not set")
		return nil, func() {}, nil
	}
	nc, err := connectNATSURL(ctx, cfg, cfg.NatsURL)
	if err != nil {
		return nil, nil, fmt.Errorf("resync nats connect: %w", err)
	}
	js, err := nc.JetStream()
	if err != nil {
		nc.Close()
		return nil, nil, fmt.Errorf("resync jetstream context: %w", err)
	}
	cleanup := func() { drainNATS(ctx, nc, "resync") }
	return newResyncWebhookPublisher(js), cleanup, nil
}

package permssweep

import (
	"context"
	"fmt"
	"log/slog"
	"time"

	"github.com/entireio/go-nuts/natsmsg"
	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	otelcodes "go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"entire.io/slogutil"
)

const tracerName = "entire.io/internal/entirecore/permssweep"

// natsMsgIDHeader is the JetStream dedup header (same constant gitjobs and
// permsbackfill use; spelt out to avoid pulling in nats.go's internal const).
const natsMsgIDHeader = "Nats-Msg-Id"

// publishTimeout bounds one synchronous PublishMsg round-trip. Load-bearing:
// the enumerator's ctx has no deadline, and PublishMsg with a deadline-free
// nats.Context waits for the PubAck indefinitely — with RetryOnFailedConnect
// the connect itself "succeeds" while NATS is down, so an unbounded publish
// would hang the CronJob forever instead of failing the tick loudly (the
// exact never-terminating-Job failure mode this fan-out exists to kill).
const publishTimeout = 15 * time.Second

// JetStreamPublisher is the slice of nats.JetStreamContext the Publisher
// needs, pulled out so tests can stub publish without a live JetStream.
type JetStreamPublisher interface {
	PublishMsg(m *nats.Msg, opts ...nats.PubOpt) (*nats.PubAck, error)
}

// Publisher emits perms_sweep jobs onto the in-cell repo_ops_v1 stream. One
// Publisher per enumerator run; the subject is fixed at construction (the
// sweep is fleet-scoped, so every job of a run rides the same subject).
type Publisher struct {
	js      JetStreamPublisher
	subject string
}

// NewPublisher binds a Publisher to a JetStream context and the enumerator's
// jurisdiction (empty publishes under the "global" token).
func NewPublisher(js JetStreamPublisher, jurisdiction string) *Publisher {
	return &Publisher{js: js, subject: subjectFor(jurisdiction)}
}

// publishMsg is the mechanical tail every perms_sweep publish shares —
// enumerator jobs, canaries, and the consumer's chunk continuations: build
// the message, stamp the JetStream dedup id, inject trace context, and run a
// publishTimeout-bounded PublishMsg (see publishTimeout for why the bound is
// load-bearing). Callers own their spans, metrics, and logging.
func publishMsg(ctx context.Context, js JetStreamPublisher, subject, msgID string, data []byte) (*nats.PubAck, error) {
	msg := &nats.Msg{Subject: subject, Data: data, Header: nats.Header{}}
	msg.Header.Set(natsMsgIDHeader, msgID)
	otel.GetTextMapPropagator().Inject(ctx, natsmsg.HeaderCarrier(msg.Header))
	pubCtx, cancel := context.WithTimeout(ctx, publishTimeout)
	defer cancel()
	return js.PublishMsg(msg, nats.Context(pubCtx)) //nolint:wrapcheck // every caller wraps with its own publish context
}

// PublishSweep enqueues one per-installation sweep job carrying the
// enumerator's staleness cutoff. The Nats-Msg-Id (op/installation_id)
// collapses same-tick producer retries inside the stream's duplicates
// window; cross-tick duplicates are deliberately allowed and neutralized by
// the worker's consume-time work-list re-check.
func (p *Publisher) PublishSweep(ctx context.Context, installationID int64, staleBefore time.Time) error {
	ctx, span := otel.Tracer(tracerName).Start(ctx, "perms.sweep.publish",
		trace.WithSpanKind(trace.SpanKindProducer),
		trace.WithAttributes(
			attribute.String("messaging.system", "nats"),
			attribute.String("messaging.operation.type", "publish"),
			attribute.String("messaging.destination.name", p.subject),
			attribute.Int64("entire.github.installation_id", installationID),
		),
	)
	defer span.End()

	data, err := encodeEvent(installationID, staleBefore)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "encode sweep job")
		return fmt.Errorf("encode sweep job: %w", err)
	}

	msgID := fmt.Sprintf("%s/%d", op, installationID)
	span.SetAttributes(attribute.String("messaging.message.id", msgID))

	ack, err := publishMsg(ctx, p.js, p.subject, msgID, data)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "nats publish")
		recordInstallationPublished(ctx, "error")
		return fmt.Errorf("publish perms sweep: %w", err)
	}
	recordInstallationPublished(ctx, "ok")
	span.SetAttributes(
		attribute.Int64("messaging.nats.sequence", natsmsg.ClampToInt64(ack.Sequence)),
		attribute.Bool("messaging.nats.duplicate", ack.Duplicate),
	)
	slogutil.Debug(ctx, "published perms sweep job",
		slog.String("subject", p.subject),
		slog.String("msg_id", msgID),
		slog.Int64("installation_id", installationID),
		slog.Bool("duplicate", ack.Duplicate),
	)
	return nil
}

// PublishCanary enqueues the enumerator's per-run liveness canary (see
// event.Canary). Deliberately NOT counted in installations_published — that
// counter is real sweep throughput. The constant Nats-Msg-Id only collapses
// same-tick producer retries: hourly ticks are far outside the stream's 10s
// duplicates window, so every run's canary is delivered.
func (p *Publisher) PublishCanary(ctx context.Context) error {
	ctx, span := otel.Tracer(tracerName).Start(ctx, "perms.sweep.publish_canary",
		trace.WithSpanKind(trace.SpanKindProducer),
		trace.WithAttributes(
			attribute.String("messaging.system", "nats"),
			attribute.String("messaging.operation.type", "publish"),
			attribute.String("messaging.destination.name", p.subject),
			attribute.Bool("entire.permssweep.canary", true),
		),
	)
	defer span.End()

	data, err := encodeCanaryEvent()
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "encode sweep canary")
		return fmt.Errorf("encode sweep canary: %w", err)
	}

	msgID := op + "/canary"
	span.SetAttributes(attribute.String("messaging.message.id", msgID))

	ack, err := publishMsg(ctx, p.js, p.subject, msgID, data)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "nats publish")
		return fmt.Errorf("publish perms sweep canary: %w", err)
	}
	span.SetAttributes(
		attribute.Int64("messaging.nats.sequence", natsmsg.ClampToInt64(ack.Sequence)),
		attribute.Bool("messaging.nats.duplicate", ack.Duplicate),
	)
	slogutil.Debug(ctx, "published perms sweep canary",
		slog.String("subject", p.subject),
		slog.Bool("duplicate", ack.Duplicate),
	)
	return nil
}

package permsbackfill

import (
	"context"
	"fmt"
	"log/slog"

	"github.com/entireio/go-nuts/natsmsg"
	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	otelcodes "go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"entire.io/slogutil"
)

const tracerName = "entire.io/internal/entirecore/permsbackfill"

// natsMsgIDHeader is the JetStream dedup header (same constant gitjobs uses;
// spelt out to avoid pulling in nats.go's internal const).
const natsMsgIDHeader = "Nats-Msg-Id"

// JetStreamPublisher is the slice of nats.JetStreamContext the Publisher needs,
// pulled out so tests can stub publish without a live JetStream.
type JetStreamPublisher interface {
	PublishMsg(m *nats.Msg, opts ...nats.PubOpt) (*nats.PubAck, error)
}

// Publisher emits perms_backfill jobs onto the per-cell repo_ops_v1 stream. One
// Publisher targets one in-cell JetStream — the regional core is co-located
// with the single cluster it serves.
type Publisher struct {
	js JetStreamPublisher
}

// NewPublisher binds a Publisher to a JetStream context.
func NewPublisher(js JetStreamPublisher) *Publisher {
	return &Publisher{js: js}
}

// PublishBackfill enqueues one collaborator-reconcile job for an upstream.
// Idempotent within the stream's dedup window on (op, cluster, github_repo_id):
// a retry of the same create collapses server-side. The caller treats a publish
// error as best-effort — the periodic reconciler is the authoritative backstop
// — so a NATS blip never fails the create it rode in on.
func (p *Publisher) PublishBackfill(ctx context.Context, jurisdiction, cluster string, githubRepoID int64) error {
	subject := subjectFor(jurisdiction, cluster)
	ctx, span := otel.Tracer(tracerName).Start(ctx, "mirror.perms.backfill.publish",
		trace.WithSpanKind(trace.SpanKindProducer),
		trace.WithAttributes(
			attribute.String("messaging.system", "nats"),
			attribute.String("messaging.operation.type", "publish"),
			attribute.String("messaging.destination.name", subject),
			attribute.Int64("entire.github_repo_id", githubRepoID),
			attribute.String("entire.target_jurisdiction", jurisdiction),
			attribute.String("entire.target_cluster", cluster),
		),
	)
	defer span.End()

	data, err := encodeEvent(githubRepoID)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "encode backfill")
		return fmt.Errorf("encode backfill: %w", err)
	}

	// Dedup key: op/cluster/repo. A retry of the same create-mirror call
	// collapses; a different upstream (or the same upstream on another cluster)
	// gets a distinct key.
	msgID := fmt.Sprintf("%s/%s/%d", op, cluster, githubRepoID)
	msg := &nats.Msg{Subject: subject, Data: data, Header: nats.Header{}}
