// rateLimitNakDelay sizes a rate-limited job's redelivery delay to the reset
// window carried by the error, clamped to [nakDelay, rateLimitMaxNakDelay]
// with a little slack past the reset; without a usable reset instant it falls
// back to rateLimitFallbackNakDelay.
func rateLimitNakDelay(err error, now time.Time) time.Duration {
	rl, ok := errors.AsType[*githubapi.RateLimitError](err)
	if !ok || rl.ResetAt.IsZero() {
		return rateLimitFallbackNakDelay
	}
	delay := rl.ResetAt.Sub(now) + rateLimitNakSlack
	return min(max(delay, nakDelay), rateLimitMaxNakDelay)
}

// publishContinuation re-enqueues the delivered job — same subject, same
// installation, same staleness cutoff — so the next chunk of a large
// installation runs with a fresh delivery budget. The Nats-Msg-Id is keyed on
// this delivery's stream sequence: unique against the enumerator's own
// perms_sweep/<id> publishes, while a redelivered chunk that re-publishes its
// continuation inside the duplicates window collapses to one message.
func (c *Consumer) publishContinuation(ctx context.Context, msg jetstream.Msg, ev event) error {
	data, err := encodeEvent(ev.InstallationID, ev.StaleBefore)
	if err != nil {
		return fmt.Errorf("encode continuation: %w", err)
	}
	var seq uint64
	if meta, merr := msg.Metadata(); merr == nil && meta != nil {
		seq = meta.Sequence.Stream
	}
	msgID := fmt.Sprintf("%s/%d/cont/%d", op, ev.InstallationID, seq)
	if _, err := publishMsg(ctx, c.cfg.Continuations, msg.Subject(), msgID, data); err != nil {
		return fmt.Errorf("publish continuation: %w", err)
	}
	return nil
}

// deliveryCount is the message's NumDelivered (1 on first delivery), or 1 when
// metadata is unavailable (e.g. a non-JetStream test message).
func deliveryCount(msg jetstream.Msg) uint64 {
	if meta, err := msg.Metadata(); err == nil && meta != nil {
		return meta.NumDelivered
	}
	return 1
}

// disposePoison captures a permanently-unprocessable message to the DLQ and
// then Acks it — the only way to remove it from the WorkQueue (Term/MaxDeliver
// leave it to linger to StreamMaxAge, COR-944). On a DLQ publish failure it Naks
// instead of Acking, so poison is never dropped without a captured copy.
func (c *Consumer) disposePoison(ctx context.Context, msg jetstream.Msg, reason string, cause error) {
	subject := dlqSubjectPrefix + op + "." + natsmsg.SubjectToken(reason)
	if dlqErr := natsmsg.DeadLetter(ctx, c.cfg.DLQ, subject, msg, reason); dlqErr != nil {
		slogutil.Error(ctx, "perms-sweep dead-letter publish failed; naking (poison retained, not dropped)",
			slog.String("reason", reason),
			slog.String("subject", msg.Subject()),
			slog.String("dlq_error", dlqErr.Error()),
			slog.String("cause", cause.Error()),
		)
		if nakErr := msg.NakWithDelay(nakDelay); nakErr != nil {
			slogutil.Warn(ctx, "perms-sweep nak after dead-letter failure failed", slog.String("error", nakErr.Error()))
		}
		recordJobFinished(ctx, "failed")
		return
	}
	recordJobFinished(ctx, "dead_lettered")
	if ackErr := msg.Ack(); ackErr != nil {
		slogutil.Warn(ctx, "perms-sweep dead-letter ack failed", slog.String("error", ackErr.Error()))
	}
}

