package gitjobs

import (
	"context"
	"testing"

	"github.com/nats-io/nats.go"
)

// capturingJS records the subjects it was asked to publish.
type capturingJS struct {
	subjects []string
}

func (c *capturingJS) PublishMsg(m *nats.Msg, _ ...nats.PubOpt) (*nats.PubAck, error) {
	c.subjects = append(c.subjects, m.Subject)
	return &nats.PubAck{Stream: StreamName, Sequence: 1}, nil
}

func TestPublishSyncRepoComposesSubject(t *testing.T) {
	js := &capturingJS{}
	p := NewPublisher(js)

	err := p.PublishSyncRepo(context.Background(),
		Placement{Jurisdiction: "eu", ClusterID: "aws-eu-central-1"},
		Source{Owner: "dvydra", Repo: "guardian-api-parser"},
		Target{ULID: "01KSS075V75V0NN9FAKSFD4JD3"},
	)
	if err != nil {
		t.Fatalf("PublishSyncRepo: %v", err)
	}
	want := "mirror.git.v1.eu.aws-eu-central-1.github.sync_repo"
	if len(js.subjects) != 1 || js.subjects[0] != want {
		t.Fatalf("subjects = %v, want [%q]", js.subjects, want)
	}
}

