package repoops

import (
	"context"
	"errors"
	"strings"
	"testing"
	"time"

	"github.com/nats-io/nats.go"
)

type fakeJetStreamPublisher struct {
	msgs []*nats.Msg
	err  error
}

func (f *fakeJetStreamPublisher) PublishMsg(m *nats.Msg, _ ...nats.PubOpt) (*nats.PubAck, error) {
	if f.err != nil {
		return nil, f.err
	}
	f.msgs = append(f.msgs, m)
	return &nats.PubAck{}, nil
}

func TestPublishTeardownDedupKeyIncludesObservationTime(t *testing.T) {
	js := &fakeJetStreamPublisher{}
	p := NewPublisher(js)
	placement := Placement{Jurisdiction: "eu", ClusterSlug: "royalcanin"}
	target := Target{ULID: "01ARZ3NDEKTSV4RRFFQ69G5FAV"}
	firstRemoval := time.Date(2026, 6, 22, 12, 0, 0, 0, time.UTC)
	secondRemoval := firstRemoval.Add(time.Second)

	if err := p.PublishTeardown(context.Background(), placement, target, 42, firstRemoval); err != nil {
		t.Fatalf("PublishTeardown(first): %v", err)
	}
	if err := p.PublishTeardown(context.Background(), placement, target, 42, firstRemoval); err != nil {
		t.Fatalf("PublishTeardown(retry): %v", err)
	}
	if err := p.PublishTeardown(context.Background(), placement, target, 42, secondRemoval); err != nil {
		t.Fatalf("PublishTeardown(second removal): %v", err)
	}
	if len(js.msgs) != 3 {
		t.Fatalf("published %d messages, want 3", len(js.msgs))
	}

	firstID := js.msgs[0].Header.Get(NatsMsgIDHeader)
	retryID := js.msgs[1].Header.Get(NatsMsgIDHeader)
	secondID := js.msgs[2].Header.Get(NatsMsgIDHeader)
	if firstID == "" || retryID == "" || secondID == "" {
		t.Fatalf("missing %s header: %q %q %q", NatsMsgIDHeader, firstID, retryID, secondID)
	}
	if firstID != retryID {
		t.Fatalf("same removal observation dedup IDs differ: %q != %q", firstID, retryID)
	}
	if firstID == secondID {
		t.Fatalf("new removal observation reused dedup ID %q; this can lose teardown after a re-add", firstID)
	}
}

func TestPublishOpsSubjectAndDedupKeyCarryTheOp(t *testing.T) {
	js := &fakeJetStreamPublisher{}
	p := NewPublisher(js)
	placement := Placement{Jurisdiction: "eu", ClusterSlug: "royalcanin"}
	target := Target{ULID: "01ARZ3NDEKTSV4RRFFQ69G5FAV"}
