	if err := p.PublishAppSuspend(context.Background(), placement, target, 42, 555, observed); err != nil {
		t.Fatalf("PublishAppSuspend: %v", err)
	}
	if err := p.PublishResume(context.Background(), placement, target, 42, observed); err != nil {
		t.Fatalf("PublishResume: %v", err)
	}
	if err := p.PublishTeardown(context.Background(), placement, target, 42, observed); err != nil {
		t.Fatalf("PublishTeardown: %v", err)
	}
	if len(js.msgs) != 3 {
		t.Fatalf("published %d messages, want 3", len(js.msgs))
	}

	wantSubjects := []string{
		"repo.ops.v1.eu.royalcanin.suspend",
		"repo.ops.v1.eu.royalcanin.resume",
		"repo.ops.v1.eu.royalcanin.teardown",
	}
	ids := make(map[string]bool, 3)
	for i, msg := range js.msgs {
		if msg.Subject != wantSubjects[i] {
			t.Errorf("msgs[%d].Subject = %q, want %q", i, msg.Subject, wantSubjects[i])
		}
