		if id == "" {
			t.Fatalf("msgs[%d] missing %s dedup header", i, NatsMsgIDHeader)
		}
		// The op is the leading msg-id token: the same placement + observation
		// can legitimately carry a suspend AND a resume (or teardown), and they
		// must not collapse into one job in the duplicates window.
		wantPrefix := strings.SplitAfter(wantSubjects[i], "royalcanin.")[1] + "/"
		if !strings.HasPrefix(id, wantPrefix) {
			t.Errorf("msgs[%d] msg-id = %q, want prefix %q", i, id, wantPrefix)
		}
		if ids[id] {
			t.Errorf("msgs[%d] reuses msg-id %q across ops; distinct ops must not dedup together", i, id)
		}
		ids[id] = true
	}
}

func TestPublishGateVariants(t *testing.T) {
	// The App-suspend publish is the ONLY one that stamps a SuspendGate +
	// InstallationID; teardown (and resume) carry the zero gate so old
	// consumers and the removal-gate back-compat branch decode them
	// unchanged. (The removal-driven PublishSuspend is gone — COR-454.)
