	p := NewPublisher(js)
	placement := Placement{Jurisdiction: "eu", ClusterSlug: "royalcanin"}
	target := Target{ULID: "01ARZ3NDEKTSV4RRFFQ69G5FAV"}
	observed := time.Date(2026, 7, 3, 9, 0, 0, 0, time.UTC)

