		t.Errorf("PublishTeardown job = gate %q / inst %d, want zero gate / 0", teardown.SuspendGate, teardown.InstallationID)
	}

	app, err := Unmarshal(js.msgs[1].Data)
	if err != nil {
		t.Fatalf("unmarshal app suspend: %v", err)
	}
	if app.SuspendGate != SuspendGateInstallationSuspended || app.InstallationID != 555 {
		t.Errorf("PublishAppSuspend job = gate %q / inst %d, want installation_suspended / 555", app.SuspendGate, app.InstallationID)
	}
}

func TestPublishTeardownReturnsPublishError(t *testing.T) {
	p := NewPublisher(&fakeJetStreamPublisher{err: errors.New("nats down")})
	err := p.PublishTeardown(context.Background(),
		Placement{Jurisdiction: "eu", ClusterSlug: "royalcanin"},
		Target{ULID: "01ARZ3NDEKTSV4RRFFQ69G5FAV"},
		42,
		time.Date(2026, 6, 22, 12, 0, 0, 0, time.UTC),
	)
	if err == nil {
		t.Fatal("PublishTeardown = nil, want publish error")
	}
}

