package permswebhook

import (
	"context"
	"testing"
	"time"

	"github.com/nats-io/nats.go"
)

// nopApplier satisfies eventApplier for config-defaulting tests that never
// process a message.
type nopApplier struct{}

func (nopApplier) apply(context.Context, string, string, time.Time, []byte) error { return nil }

// TestNewDefaultsUnlimitedMaxDeliver pins the redelivery budget at unlimited.
// The metadata consumer's writes are idempotent and observedAt-gated, and the
// suspend/teardown fan-outs it drives are NOT re-derivable (GitHub never
// resends the event) — a finite cap plus a ~1-minute repo_ops publish outage
// would exhaust deliveries server-side (no client signal) and permanently
// drop the fan-out, leaving live grants behind. Poison payloads Term via
// permanent(), so unlimited retry only ever rides out transient failures.
func TestNewDefaultsUnlimitedMaxDeliver(t *testing.T) {
	c, err := New(Config{Conn: &nats.Conn{}, Applier: nopApplier{}})
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	if c.cfg.MaxDeliver >= 0 {
		t.Errorf("MaxDeliver = %d, want unlimited (< 0)", c.cfg.MaxDeliver)
	}
}

// TestNewDefaultsInactiveThreshold pins that the 72h reap window is carried on
// the consumer config (it now rides the CreateOrUpdateConsumer upsert rather
// than a separate reconcile step).
func TestNewDefaultsInactiveThreshold(t *testing.T) {
	c, err := New(Config{Conn: &nats.Conn{}, Applier: nopApplier{}})
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	if c.cfg.InactiveThreshold != defaultInactiveThreshold {
		t.Errorf("InactiveThreshold = %v, want %v", c.cfg.InactiveThreshold, defaultInactiveThreshold)
	}
	if got := c.consumerConfig(); got.InactiveThreshold != defaultInactiveThreshold {
		t.Errorf("consumerConfig InactiveThreshold = %v, want %v", got.InactiveThreshold, defaultInactiveThreshold)
	}
}

// TestNakDelayBacksOff mirrors repoops: with MaxDeliver unlimited, the
// redelivery delay must grow with the delivery count and cap at
// RetryBackoffMx so a long-stuck message can't hammer a recovering store.
func TestNakDelayBacksOff(t *testing.T) {
	c, err := New(Config{Conn: &nats.Conn{}, Applier: nopApplier{}})
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	if got := c.nakDelay(1); got != c.cfg.NakDelay {
		t.Errorf("nakDelay(1) = %v, want base %v", got, c.cfg.NakDelay)
	}
	if got := c.nakDelay(2); got <= c.cfg.NakDelay {
		t.Errorf("nakDelay(2) = %v, want > base %v", got, c.cfg.NakDelay)
	}
	if got := c.nakDelay(1000); got != c.cfg.RetryBackoffMx {
		t.Errorf("nakDelay(1000) = %v, want cap %v", got, c.cfg.RetryBackoffMx)
	}
}

