// TestNakDelayBacksOff pins the redelivery envelope the shared
// backoff.Policy applies: geometric ×2 from the 5s base, capped at
// nakDelayMax so a long-stuck (unlimited-retry) job's churn against a
// recovering store stays bounded. The exact sequence is load-bearing — it
// predates the go-nuts migration and must not drift with the library.
func TestNakDelayBacksOff(t *testing.T) {
	c, err := New(validConfig())
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	want := map[int]time.Duration{
		0:    5 * time.Second, // metadata unavailable reads as first delivery
		1:    5 * time.Second,
		2:    10 * time.Second,
		3:    20 * time.Second,
		4:    30 * time.Second, // 40s capped at nakDelayMax
		1000: nakDelayMax,
	}
	for n, wantDelay := range want {
		if got := c.policy.DelayFor(n); got != wantDelay {
			t.Errorf("DelayFor(%d) = %v, want %v", n, got, wantDelay)
		}
	}
}

