const tracerName = "entire.io/internal/entirecore/repoops"

// NatsMsgIDHeader is the JetStream dedup header. A re-published job for
// the same op, placement, and observation within StreamDuplicatesWindow
// collapses server-side, so the producer can retry one webhook without
// enqueuing it twice. Distinct observations must not collapse: an upstream
// can be removed, re-added, then removed again inside the duplicate
// window, and the older job may legitimately skip via the
// last-writer-wins gate.
