package permsbackfill

import (
	"context"
	"fmt"
	"log/slog"

	"github.com/entireio/go-nuts/natsmsg"
	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"

	"entire.io/slogutil"
)

const tracerName = "entire.io/internal/entirecore/permsbackfill"

// JetStreamPublisher is the slice of nats.JetStreamContext the Publisher needs,
// pulled out so tests can stub publish without a live JetStream.
type JetStreamPublisher interface {
	PublishMsg(m *nats.Msg, opts ...nats.PubOpt) (*nats.PubAck, error)
}

// Publisher emits perms_backfill jobs onto the per-cell repo_ops_v1 stream. One
// Publisher targets one in-cell JetStream — the regional core is co-located
// with the single cluster it serves.
//
// The publish mechanics (producer span, trace-context injection, Nats-Msg-Id,
// bounded PubAck wait) live in the shared natsmsg.LegacyPublisher; this type
// owns the domain: subject construction, the dedup key, and the log line.
type Publisher struct {
	pub natsmsg.LegacyPublisher
}

// NewPublisher binds a Publisher to a JetStream context.
func NewPublisher(js JetStreamPublisher) *Publisher {
	return &Publisher{pub: natsmsg.LegacyPublisher{
		JS:        js,
		Tracer:    otel.Tracer(tracerName),
		Operation: "mirror.perms.backfill.publish",
	}}
}

// PublishBackfill enqueues one collaborator-reconcile job for an upstream.
// Idempotent within the stream's dedup window on (op, cluster, github_repo_id):
// a retry of the same create collapses server-side. The caller treats a publish
// error as best-effort — the periodic reconciler is the authoritative backstop
// — so a NATS blip never fails the create it rode in on.
func (p *Publisher) PublishBackfill(ctx context.Context, jurisdiction, cluster string, githubRepoID int64) error {
	subject := subjectFor(jurisdiction, cluster)
	ctx, span := otel.Tracer(tracerName).Start(ctx, "mirror.perms.backfill.publish",
		trace.WithSpanKind(trace.SpanKindProducer),
		trace.WithAttributes(
			attribute.String("messaging.system", "nats"),
			attribute.String("messaging.operation.type", "publish"),
			attribute.String("messaging.destination.name", subject),
			attribute.Int64("entire.github_repo_id", githubRepoID),
			attribute.String("entire.target_jurisdiction", jurisdiction),
			attribute.String("entire.target_cluster", cluster),
		),
	)
	defer span.End()

	data, err := encodeEvent(githubRepoID)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "encode backfill")
		return fmt.Errorf("encode backfill: %w", err)
	}

	// Dedup key: op/cluster/repo. A retry of the same create-mirror call
	// collapses; a different upstream (or the same upstream on another cluster)
	// gets a distinct key.
	msgID := fmt.Sprintf("%s/%s/%d", op, cluster, githubRepoID)
	msg := &nats.Msg{Subject: subject, Data: data, Header: nats.Header{}}
	msg.Header.Set(natsMsgIDHeader, msgID)
	otel.GetTextMapPropagator().Inject(ctx, natsmsg.HeaderCarrier(msg.Header))
	span.SetAttributes(attribute.String("messaging.message.id", msgID))

	ack, err := p.js.PublishMsg(msg, nats.Context(ctx))
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "nats publish")
		return fmt.Errorf("publish perms backfill: %w", err)
	}
	span.SetAttributes(
		attribute.Int64("messaging.nats.sequence", natsmsg.ClampToInt64(ack.Sequence)),
		attribute.Bool("messaging.nats.duplicate", ack.Duplicate),
	)
	slogutil.Info(ctx, "published perms backfill",
		slog.String("subject", subject),
		slog.String("msg_id", msgID),
		slog.Int64("github_repo_id", githubRepoID),
		slog.Bool("duplicate", ack.Duplicate),
	)
	return nil
}

