package entirecore

import (
	"context"
	"encoding/json"
	"testing"

	"github.com/nats-io/nats.go"

	"entire.io/core/mirrorrepo/gitjobs"
	"entire.io/core/model"
	"entire.io/internal/entirecore/permswebhook"
)

// captureJS records the last message a resyncWebhookPublisher publishes so the
// test can assert the subject, dedup header, and envelope/body shape without a
// live JetStream. Satisfies gitjobs.JetStreamPublisher.
type captureJS struct {
	msg *nats.Msg
}

func (c *captureJS) PublishMsg(m *nats.Msg, _ ...nats.PubOpt) (*nats.PubAck, error) {
	c.msg = m
	return &nats.PubAck{Stream: permswebhook.StreamName, Sequence: 1}, nil
}

func TestResyncWebhookPublisher_PublishesPushEnvelope(t *testing.T) {
	t.Parallel()
	js := &captureJS{}
	pub := newResyncWebhookPublisher(js)

	repoID := model.NewRepoID()
	const fullName = "entireio/cli-checkpoints"
	const installationID int64 = 123456

	if err := pub.PublishResync(context.Background(), repoID, fullName, installationID); err != nil {
		t.Fatalf("PublishResync: %v", err)
	}
	if js.msg == nil {
		t.Fatal("no message published")
	}

	// Subject is the canonical push subject fanout consumes.
	if got, want := js.msg.Subject, permswebhook.SubjectPrefix+"push"; got != want {
		t.Fatalf("subject = %q, want %q", got, want)
	}

	// Dedup header set to the delivery id so a burst collapses in the stream's
	// dedup window.
	deliveryHdr := js.msg.Header.Get(nats.MsgIdHdr)
	if deliveryHdr == "" {
		t.Fatal("missing Nats-Msg-Id dedup header")
	}

	// Envelope decodes to a valid push ForwardedWebhook.
	var env permswebhook.ForwardedWebhook
	if err := json.Unmarshal(js.msg.Data, &env); err != nil {
		t.Fatalf("decode envelope: %v", err)
	}
	if env.Event != "push" {
		t.Fatalf("event = %q, want push", env.Event)
	}
	if env.DeliveryID == "" {
		t.Fatal("empty delivery_id")
	}
	if env.DeliveryID != deliveryHdr {
		t.Fatalf("delivery_id %q != Nats-Msg-Id %q — dedup header must mirror the id", env.DeliveryID, deliveryHdr)
	}

	// Body carries exactly the two fields fanout reads: repository.full_name
	// and installation.id.
	var body resyncPushBody
	if err := json.Unmarshal(env.Body, &body); err != nil {
		t.Fatalf("decode body: %v", err)
	}
	if body.Repository.FullName != fullName {
		t.Fatalf("full_name = %q, want %q", body.Repository.FullName, fullName)
	}
	if body.Installation.ID != installationID {
		t.Fatalf("installation.id = %d, want %d", body.Installation.ID, installationID)
	}
}

