// Package settingsconsumer durably consumes the repo_settings_v1 fan-out from
// this cell's LOCAL JetStream stream and converges each event onto the local
// repo_settings row(s).
//
// The fan-out is a BROADCAST bus (DESIGN Decision 6): every settings toggle in any
// cell is broadcast into every region's island, so this consumer binds the WHOLE
// stream (repo_settings.v1.>), NOT its own jurisdiction — the jurisdiction token on
// the wire is ORIGIN-tagging for observability, not routing. For each event it
// resolves the origin (repo_group_id → local repo_id via the reverse index; a
// native repo → its own placement) and LWW-upserts the full snapshot onto each
// local placement. A cell with no placement for the event acks and skips (the
// common case — most repos are not placed in most cells). The origin cell consumes
// its own broadcast too; the LWW guard makes that an idempotent no-op.
//
// It mirrors the per-cell decode consumers (internal/githubmeta, internal/githubpr):
// a durable pull consumer, AckExplicit, MaxDeliver-bounded, Term on a poison
// payload, Nak on a transient DB error, Ack on success or a benign no-placement
// skip. The caller gates Start behind CONSUME_REPO_SETTINGS so a cell without the
// stream provisioned doesn't error at CreateOrUpdateConsumer.
package settingsconsumer

import (
	"context"
	"errors"
	"log/slog"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/entire-api/internal/otelsetup"
	"github.com/entirehq/entire-api/internal/reposettings"
	"github.com/entirehq/entire-api/internal/store"
	"github.com/entireio/go-nuts/jsconsumer"
)

// consumerDurable is the durable consumer name on each cell's repo_settings_v1
// stream. One per deployment, stable across restarts.
const consumerDurable = "repo-settings-consumer"

// consumerMaxDeliver caps redelivery before JetStream terms a message — same
// posture as the githubmeta / githubpr consumers.
const consumerMaxDeliver = 8

// consumerCfg is the durable pull-consumer descriptor. It binds the WHOLE stream
// (repo_settings.v1.>): every cell must receive every settings event, then resolve
// local placement — filtering by own jurisdiction would drop the cross-cell
// broadcasts this consumer exists to apply (DESIGN Decision 6).
var consumerCfg = jsconsumer.Config{
	Stream:        reposettings.StreamName,
	Durable:       consumerDurable,
	FilterSubject: reposettings.SubjectPrefix + ">",
	MaxDeliver:    consumerMaxDeliver,
	SpanName:      "repo_settings.consume",
	Name:          "settingsconsumer",
	// Tracer keeps consumer spans scoped to the service (otelsetup.tracerName),
	// not the go-nuts module, so trace attribution is unchanged by the migration.
	Tracer: otelsetup.Tracer(),
}

// SettingsWriter is the store surface the consumer resolves placements and applies
// LWW upserts through, satisfied by *store.RepoStore.
type SettingsWriter interface {
	LocalSettingsPlacements(ctx context.Context, repoID, repoGroupID string) ([]string, error)
	ApplySettingsLWW(ctx context.Context, r store.SettingsRow) (applied bool, err error)
}

// Consumer durably pulls repo_settings_v1 from this cell's LOCAL JetStream stream,
// bound to the WHOLE stream (broadcast=consume-all), and converges each event onto
// the local repo_settings row(s) under the LWW guard.
type Consumer struct {
	nc    *nats.Conn
	store SettingsWriter
	m     metrics

	run *jsconsumer.Runner
}

// NewConsumer constructs a Consumer over the local NATS connection and the store.
func NewConsumer(nc *nats.Conn, w SettingsWriter) *Consumer {
	return &Consumer{nc: nc, store: w, m: newMetrics()}
}

// Start creates the durable consumer and begins consuming. Returns immediately.
// The local repo_settings_v1 stream must already exist — it is provisioned
// declaratively in fleet (apps/nats-streams, nack), not by this binary. The caller
// gates Start behind CONSUME_REPO_SETTINGS so a cell without the stream provisioned
// doesn't error here.
func (c *Consumer) Start(ctx context.Context) error {
	if c == nil || c.nc == nil {
		return errors.New("settingsconsumer: Consumer not initialised")
	}
	if c.store == nil {
		return errors.New("settingsconsumer: Consumer.store required")
	}
	run, err := jsconsumer.Start(ctx, c.nc, consumerCfg, func(msg jetstream.Msg) { c.handle(ctx, msg) })
	if err != nil {
		return err
	}
	c.run = run
	slog.InfoContext(ctx, "repo_settings consumer started", slog.String("subject", consumerCfg.FilterSubject))
	return nil
}

// Stop halts the consume loop. Idempotent.
func (c *Consumer) Stop() error {
	c.run.Stop()
	return nil
}

// handle is the per-message entry point (production callback + test seam): the shared
// span+decode-or-term prologue, then onEvent for a decoded event.
func (c *Consumer) handle(ctx context.Context, msg jetstream.Msg) {
	jsconsumer.Process(ctx, msg, consumerCfg, reposettings.Unmarshal, c.onEvent, func(ctx context.Context) {
		c.m.dropped.Add(ctx, 1, attr("reason", "undecodable"))
	})
}

func (c *Consumer) onEvent(ctx context.Context, span trace.Span, msg jetstream.Msg, ev reposettings.Event) {
	// DIRECTED event (new-placement inheritance, COR-901): the sender already
	// resolved the exact target placement, so blind-write by repo_id — no local
	// placement resolution. This is deliberately decoupled from the target's repos
	// row existing: the seed rides a different stream (resource_lifecycle_v1) with
	// independent backpressure, so requiring the row here would reintroduce the
	// cross-stream race the directed push exists to avoid. There is no FK on
	// repo_setting_kv.repo_id, so the row stands alone until the seed lands.
	if ev.TargetRepoID != "" {
		ok, err := c.store.ApplySettingsLWW(ctx, store.SettingsRow{
			RepoID:      ev.TargetRepoID,
			SettingKey:  ev.SettingKey,
			Value:       ev.Value,
			UpdatedFrom: ev.OriginCluster,
			UpdatedAt:   ev.UpdatedAt,
		})
		if err != nil {
			// Transient (DB blip) — nak for redelivery; the LWW upsert is idempotent.
			span.RecordError(err)
			span.SetStatus(codes.Error, "upsert")
			slog.WarnContext(ctx, "settingsconsumer: apply directed settings failed; nak", slog.Any("error", err), slog.String("repo_id", ev.TargetRepoID))
			_ = msg.Nak()
			return
		}
		c.m.written.Add(ctx, 1, attr("mode", "directed"))
		_ = msg.Ack()
		outcome := "applied"
		if !ok {
			outcome = "noop" // lost the LWW guard (stale / a co-holder's identical push)
		}
		slog.InfoContext(ctx, "settingsconsumer: directed repo_settings event applied",
			slog.String("outcome", outcome),
			slog.String("repo_id", ev.TargetRepoID),
			slog.String("repo_group_id", ev.RepoGroupID),
			slog.String("origin_cluster", ev.OriginCluster),
			slog.Time("updated_at", ev.UpdatedAt),
			slog.String("setting_key", ev.SettingKey),
			slog.Bool("value", ev.Value),
		)
		return
	}

	// Resolve the event's origin to this cell's local placement(s). A DB blip here
	// is transient — nak for redelivery.
	placements, err := c.store.LocalSettingsPlacements(ctx, ev.RepoID, ev.RepoGroupID)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(codes.Error, "resolve")
		slog.WarnContext(ctx, "settingsconsumer: resolve local placement failed; nak", slog.Any("error", err), slog.String("origin_key", ev.OriginKey))
		_ = msg.Nak()
		return
	}
	if len(placements) == 0 {
		// No placement in this cell — the common broadcast case (most repos aren't
		// placed in most cells). A normal skip, not an error: ack so it doesn't
		// redeliver. Debug-only (Decision 6: every toggle reaches every cell).
		c.m.skipped.Add(ctx, 1)
		slog.DebugContext(ctx, "settingsconsumer: no local placement; ack+skip",
			slog.String("origin_key", ev.OriginKey), slog.String("repo_group_id", ev.RepoGroupID))
		_ = msg.Ack()
		return
	}

	applied := 0
	for _, repoID := range placements {
		row := store.SettingsRow{
			RepoID:      repoID,
			SettingKey:  ev.SettingKey,
			Value:       ev.Value,
			UpdatedFrom: ev.OriginCluster,
			UpdatedAt:   ev.UpdatedAt,
		}
		ok, err := c.store.ApplySettingsLWW(ctx, row)
		if err != nil {
			// Transient (DB blip) — nak the whole message for redelivery. The LWW
			// upsert is idempotent, so re-applying the placements already written
			// on the retry is a no-op (equal tuple).
			span.RecordError(err)
			span.SetStatus(codes.Error, "upsert")
			slog.WarnContext(ctx, "settingsconsumer: apply settings failed; nak", slog.Any("error", err), slog.String("repo_id", repoID))
			_ = msg.Nak()
			return
		}
		if ok {
			applied++
		}
		c.m.written.Add(ctx, 1)
	}
	_ = msg.Ack()

	// Settings toggles are low frequency, so one line per applied event is fine.
	// outcome distinguishes a real convergence from an idempotent no-op (a stale
	// event or the origin cell consuming its own broadcast, where the LWW guard
	// changed nothing). setting_key/value carry the toggle state; no PII/payload here.
	outcome := "applied"
	if applied == 0 {
		outcome = "noop" // every placement lost the LWW guard (stale / self-echo)
	}
	slog.InfoContext(ctx, "settingsconsumer: repo_settings event applied",
		slog.String("outcome", outcome),
		slog.String("repo_id", ev.RepoID),
		slog.String("origin_key", ev.OriginKey),
		slog.String("repo_group_id", ev.RepoGroupID),
		slog.String("origin_cluster", ev.OriginCluster),
		slog.Time("updated_at", ev.UpdatedAt),
		slog.Int("placements", len(placements)),
		slog.Int("applied", applied),
		slog.String("setting_key", ev.SettingKey),
		slog.Bool("value", ev.Value),
	)
}

package githubpr

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel/codes"

	"github.com/entirehq/entire-api/internal/otelsetup"
	"github.com/entirehq/entire-api/internal/store"
	"github.com/entireio/go-nuts/natsmsg"
)

// consumerDurable is the durable consumer name on each cell's github_pr_v1
// stream. One per deployment, stable across restarts.
const consumerDurable = "github-pr-consumer"

// consumerMaxDeliver caps redelivery before JetStream terms a message — same
// posture as the github_meta / forwarder / ingest consumers.
const consumerMaxDeliver = 8

// PullRequestWriter is the store sink the consumer upserts PR metadata into.
type PullRequestWriter interface {
	UpsertGitHubPullRequestMeta(ctx context.Context, m store.GitHubPullRequestMeta) error
}

// Consumer durably pulls github_pr_v1 from this cell's LOCAL JetStream stream,
// filtered to this placement's (jurisdiction, cluster) subject, and upserts each
// event into the local repo store keyed by (repo ULID, PR number).
//
// Display metadata only — it NEVER gates access. The producer (mirror-pipeline
// meta-fanout) publishes one Event per resolved placement into that placement's
// local NATS, so this consumer only ever sees events for repos in this cell.
type Consumer struct {
	nc           *nats.Conn
	store        PullRequestWriter
	jurisdiction string
	cluster      string
	m            metrics

	cc jetstream.ConsumeContext
}

// NewConsumer constructs a Consumer.
func NewConsumer(nc *nats.Conn, w PullRequestWriter, jurisdiction, cluster string) *Consumer {
	return &Consumer{nc: nc, store: w, jurisdiction: jurisdiction, cluster: cluster, m: newMetrics()}
}

// Start creates the durable consumer and begins consuming. Returns immediately.
// The local github_pr_v1 stream must already exist — it is provisioned
// declaratively in fleet (apps/nats-streams), not by this binary. The caller
// gates Start behind CONSUME_PULL_REQUESTS so a cell without the stream
// provisioned doesn't error here.
func (c *Consumer) Start(ctx context.Context) error {
	if c == nil || c.nc == nil {
		return errors.New("githubpr: Consumer not initialised")
	}
	if c.store == nil {
		return errors.New("githubpr: Consumer.store required")
	}
	js, err := jetstream.New(c.nc)
	if err != nil {
		return fmt.Errorf("githubpr: jetstream.New: %w", err)
	}
	subject := SubjectFor(c.jurisdiction, c.cluster)
	cons, err := js.CreateOrUpdateConsumer(ctx, StreamName, jetstream.ConsumerConfig{
		Durable:       consumerDurable,
		AckPolicy:     jetstream.AckExplicitPolicy,
		AckWait:       30 * time.Second,
		MaxDeliver:    consumerMaxDeliver,
		FilterSubject: subject,
	})
	if err != nil {
		return fmt.Errorf("githubpr: create consumer %s/%s: %w", StreamName, consumerDurable, err)
	}
	cc, err := cons.Consume(func(msg jetstream.Msg) { c.handle(ctx, msg) })
	if err != nil {
		return fmt.Errorf("githubpr: consume %s: %w", subject, err)
	}
	c.cc = cc
	go func() {
		<-ctx.Done()
		_ = c.Stop()
	}()
	slog.InfoContext(ctx, "github_pr consumer started",
		slog.String("jurisdiction", c.jurisdiction), slog.String("cluster", c.cluster), slog.String("subject", subject))
	return nil
}

// Stop halts the consume loop. Idempotent.
func (c *Consumer) Stop() error {
	if c.cc != nil {
		c.cc.Stop()
		c.cc = nil
	}
	return nil
}

func (c *Consumer) handle(ctx context.Context, msg jetstream.Msg) {
	// Re-parent to the producer's publish span across the NATS hop.
	ctx, span := natsmsg.StartConsumerSpan(ctx, otelsetup.Tracer(), msg, "github_pr.consume")
	defer span.End()

	var ev Event
	if err := json.Unmarshal(msg.Data(), &ev); err != nil {
		// Poison payload — redelivery won't help. Term so it doesn't cycle.
		span.RecordError(err)
		span.SetStatus(codes.Error, "decode")
		slog.WarnContext(ctx, "githubpr: decode github_pr_v1; term", slog.Any("error", err), slog.String("subject", msg.Subject()))
		c.m.dropped.Add(ctx, 1, attr("reason", "undecodable"))
		_ = msg.Term()
		return
	}
	if ev.RepoULID == "" || ev.Number == 0 {
		// No key to upsert on — redelivery won't help. Term.
		slog.WarnContext(ctx, "githubpr: github_pr_v1 missing repo_ulid or number; term",
			slog.String("subject", msg.Subject()), slog.String("repo_ulid", ev.RepoULID), slog.Int("number", ev.Number))
		c.m.dropped.Add(ctx, 1, attr("reason", "missing_key"))
		_ = msg.Term()
		return
	}
	ctx = otelsetup.WithBaggage(ctx, otelsetup.RepoIDAttr(ev.RepoULID))
	if err := c.store.UpsertGitHubPullRequestMeta(ctx, toRow(ev)); err != nil {
		// Transient (DB blip) — nak for redelivery.
		span.RecordError(err)
		span.SetStatus(codes.Error, "upsert")
		slog.WarnContext(ctx, "githubpr: upsert github_pull_request_meta failed; nak",
			slog.Any("error", err), slog.String("repo_ulid", ev.RepoULID), slog.Int("number", ev.Number))
		_ = msg.Nak()
		return
	}
	c.m.written.Add(ctx, 1)
	_ = msg.Ack()
	// PR webhooks are low frequency, so a per-event success line is fine.
	slog.InfoContext(ctx, "githubpr: github_pull_request_meta upserted",
		slog.String("repo_ulid", ev.RepoULID), slog.Int("number", ev.Number))
}

// toRow maps a decoded wire Event to the store row. Fields are copied verbatim;
// observed_at carries the producer's webhook-receipt time, the store's reorder
// guard. FullName is intentionally dropped — the serve path reads full_name from
// repos/github_repo_meta, keeping repo_id the single key.
func toRow(ev Event) store.GitHubPullRequestMeta {
	return store.GitHubPullRequestMeta{
		RepoID:     ev.RepoULID,
		Number:     ev.Number,
		GitHubPRID: ev.GitHubPRID,
		Title:      ev.Title,
		HTMLURL:    ev.HTMLURL,
		State:      ev.State,
		Draft:      ev.Draft,
		HeadBranch: ev.HeadBranch,
		UserLogin:  ev.UserLogin,
		Body:       ev.Body,
		CreatedAt:  ev.CreatedAt,
		UpdatedAt:  ev.UpdatedAt,
		MergedAt:   ev.MergedAt,
		ObservedAt: ev.ObservedAt,
	}
}

// Start creates the durable consumer and begins consuming. Returns immediately.
// The local github_meta_v1 stream must already exist — it is provisioned
// declaratively in fleet (apps/nats-streams, nack), not by this binary. The
// caller gates Start behind CONSUME_GITHUB_META so a cell without the stream
// provisioned doesn't error here.
func (c *Consumer) Start(ctx context.Context) error {
	if c == nil || c.nc == nil {
		return errors.New("githubmeta: Consumer not initialised")
	}
	if c.store == nil {
		return errors.New("githubmeta: Consumer.store required")
	}
	js, err := jetstream.New(c.nc)
	if err != nil {
		return fmt.Errorf("githubmeta: jetstream.New: %w", err)
	}
	subject := SubjectFor(c.jurisdiction, c.cluster)
	cons, err := js.CreateOrUpdateConsumer(ctx, StreamName, jetstream.ConsumerConfig{
		Durable:       consumerDurable,
		AckPolicy:     jetstream.AckExplicitPolicy,
		AckWait:       30 * time.Second,
		MaxDeliver:    consumerMaxDeliver,
		FilterSubject: subject,
	})
	if err != nil {
		return fmt.Errorf("githubmeta: create consumer %s/%s: %w", StreamName, consumerDurable, err)
	}
	cc, err := cons.Consume(func(msg jetstream.Msg) { c.handle(ctx, msg) })
	if err != nil {
		return fmt.Errorf("githubmeta: consume %s: %w", subject, err)
	}
	c.cc = cc
	go func() {
		<-ctx.Done()
		_ = c.Stop()
	}()
	slog.InfoContext(ctx, "github_meta consumer started",
		slog.String("jurisdiction", c.jurisdiction), slog.String("cluster", c.cluster), slog.String("subject", subject))
	return nil
}

// Stop halts the consume loop. Idempotent.
func (c *Consumer) Stop() error {
	if c.cc != nil {
		c.cc.Stop()
		c.cc = nil
	}
	return nil
}

func (c *Consumer) handle(ctx context.Context, msg jetstream.Msg) {
	// Re-parent to the producer's publish span across the NATS hop.
	ctx, span := natsmsg.StartConsumerSpan(ctx, otelsetup.Tracer(), msg, "github_meta.consume")
	defer span.End()

	var ev Event
	if err := json.Unmarshal(msg.Data(), &ev); err != nil {
		// Poison payload — redelivery won't help. Term so it doesn't cycle.
		span.RecordError(err)
		span.SetStatus(codes.Error, "decode")
		slog.WarnContext(ctx, "githubmeta: decode github_meta_v1; term", slog.Any("error", err), slog.String("subject", msg.Subject()))
		c.m.dropped.Add(ctx, 1, attr("reason", "undecodable"))
		_ = msg.Term()
		return
	}
	if ev.RepoULID == "" {
		// No key to upsert on — redelivery won't help. Term.
		slog.WarnContext(ctx, "githubmeta: github_meta_v1 missing repo_ulid; term", slog.String("subject", msg.Subject()))
		c.m.dropped.Add(ctx, 1, attr("reason", "missing_repo_ulid"))
		_ = msg.Term()
		return
	}
	ctx = otelsetup.WithBaggage(ctx, otelsetup.RepoIDAttr(ev.RepoULID))
	if err := c.store.UpsertGitHubRepoMeta(ctx, toRow(ev)); err != nil {
		// Transient (DB blip) — nak for redelivery.
		span.RecordError(err)
		span.SetStatus(codes.Error, "upsert")
		slog.WarnContext(ctx, "githubmeta: upsert github_repo_meta failed; nak", slog.Any("error", err), slog.String("repo_ulid", ev.RepoULID))
		_ = msg.Nak()
		return
	}
	c.m.written.Add(ctx, 1)
	_ = msg.Ack()
	// Metadata webhooks are low frequency, so a per-event success line is fine.
	slog.InfoContext(ctx, "githubmeta: github_repo_meta upserted", slog.String("repo_ulid", ev.RepoULID))
}

// toRow maps a decoded wire Event to the store row. Display fields are copied
// verbatim; observed_at carries the producer's webhook-receipt time, which is
