package userlifecycle

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel/codes"

	"github.com/entirehq/entire-api/internal/otelsetup"
	"github.com/entireio/go-nuts/natsmsg"
)

// consumerDurable is the durable consumer name on each cell's
// resource_lifecycle_v1 stream. One per deployment, stable across restarts;
// distinct from the repo-seeding consumer (repo-lifecycle-consumer) and the
// re-attribution consumer (author-reattribute-consumer) that bind other arms of
// the same stream.
const consumerDurable = "user-lifecycle-consumer"

// consumerMaxDeliver caps redelivery before JetStream terms a message — same
// posture as the repo lifecycle / reattribute consumers.
const consumerMaxDeliver = 8

// Store is the user-store surface this consumer needs: the account-scoped purge.
type Store interface {
	DeleteUserData(ctx context.Context, accountID string) error
}

// Consumer durably pulls the user arm of this cell's local resource_lifecycle_v1
// stream and purges a deleted account's rows from the user store.
type Consumer struct {
	nc    *nats.Conn
	store Store
	m     metrics

	cc jetstream.ConsumeContext
}

// NewConsumer constructs a Consumer over the user store.
func NewConsumer(nc *nats.Conn, st Store) *Consumer {
	return &Consumer{nc: nc, store: st, m: newMetrics()}
}

// Start creates the durable consumer and begins consuming. Returns immediately.
// The local resource_lifecycle_v1 stream must already exist (provisioned in
// fleet); the caller gates Start behind CONSUME_USER_LIFECYCLE so a cell without
// the stream doesn't error in CreateOrUpdateConsumer.
func (c *Consumer) Start(ctx context.Context) error {
	if c == nil || c.nc == nil {
		return errors.New("userlifecycle: Consumer not initialised")
	}
	if c.store == nil {
		return errors.New("userlifecycle: Consumer.store required")
	}
	js, err := jetstream.New(c.nc)
	if err != nil {
		return fmt.Errorf("userlifecycle: jetstream.New: %w", err)
	}
	cons, err := js.CreateOrUpdateConsumer(ctx, StreamName, jetstream.ConsumerConfig{
		Durable:        consumerDurable,
		AckPolicy:      jetstream.AckExplicitPolicy,
		AckWait:        30 * time.Second,
		MaxDeliver:     consumerMaxDeliver,
		FilterSubjects: []string{subjectUser},
	})
	if err != nil {
		return fmt.Errorf("userlifecycle: create consumer %s/%s: %w", StreamName, consumerDurable, err)
	}
	cc, err := cons.Consume(func(msg jetstream.Msg) { c.handle(ctx, msg) })
	if err != nil {
		return fmt.Errorf("userlifecycle: consume %s: %w", StreamName, err)
	}
	c.cc = cc
	go func() {
		<-ctx.Done()
		_ = c.Stop()
	}()
	slog.InfoContext(ctx, "resource_lifecycle user purge consumer started")
	return nil
}

// Stop halts the consume loop. Idempotent.
func (c *Consumer) Stop() error {
	if c.cc != nil {
		c.cc.Stop()
		c.cc = nil
	}
	return nil
}

func (c *Consumer) handle(ctx context.Context, msg jetstream.Msg) {
	// Re-parent to the producer's publish span across the NATS hop.
	ctx, span := natsmsg.StartConsumerSpan(ctx, otelsetup.Tracer(), msg, "userlifecycle.consume")
	defer span.End()

	var ev Event
	if err := json.Unmarshal(msg.Data(), &ev); err != nil {
		// Poison payload — redelivery won't help. Term.
		span.RecordError(err)
		span.SetStatus(codes.Error, "decode")
		slog.WarnContext(ctx, "userlifecycle: decode resource_lifecycle_v1; term", slog.Any("error", err), slog.String("subject", msg.Subject()))
		c.m.dropped.Add(ctx, 1, attr("reason", "undecodable"))
		_ = msg.Term()
		return
	}
	if ev.ResourceType != typeUser {
		// The filter subject is the user arm, so this is defensive only — ack rather
		// than churn redelivery on a misrouted event.
		c.m.skipped.Add(ctx, 1, attr("reason", "not_user"))
		_ = msg.Ack()
		return
	}
	if ev.ResourceID == "" {
		// No account to act on — redelivery won't help. Term.
		slog.WarnContext(ctx, "userlifecycle: event missing account id; term", slog.String("subject", msg.Subject()))
		c.m.dropped.Add(ctx, 1, attr("reason", "missing_account"))
		_ = msg.Term()
		return
	}

	switch ev.Op {
	case opDeleted:
		if err := c.store.DeleteUserData(ctx, ev.ResourceID); err != nil {
			span.RecordError(err)
			span.SetStatus(codes.Error, "purge")
			slog.WarnContext(ctx, "userlifecycle: purge user failed; nak", slog.Any("error", err), slog.String("account_id", ev.ResourceID))
			_ = msg.Nak()
			return
		}
		c.m.purged.Add(ctx, 1)
		_ = msg.Ack()
		// Account deletions are low frequency; this line doubles as a purge audit trail.
		slog.InfoContext(ctx, "userlifecycle: user data purged", slog.String("account_id", ev.ResourceID))
	default:
		// An op this consumer doesn't act on (additive producer contract) — ack.
		c.m.skipped.Add(ctx, 1, attr("reason", "unhandled_op"))
		_ = msg.Ack()
	}
}

package forwarder

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/codes"

	"github.com/entirehq/entire-api/internal/otelsetup"
	"github.com/entirehq/entire-api/internal/store"
	"github.com/entireio/go-nuts/natsmsg"
)

// activityDurable is the durable consumer name on each cluster's
// user_activity_v1 stream. One per deployment, stable across restarts.
// Fixed (not configurable): it names the activity service's user-side
// consumer, paired with the repo-side ingest durable (activity-ingester).
const activityDurable = "activity-consumer"

// activityMaxDeliver caps redelivery before JetStream terms a message (sent
// to the dead-letter / surfaced) — same posture as the ingest pipeline.
const activityMaxDeliver = 8

// ActivityWriter is the store sink the consumer writes forwarded rows to.
// EnrichMyActivityFacets applies a facet enrichment event as an UPDATE of the
// facet columns on the existing row(s); it never inserts.
type ActivityWriter interface {
	UpsertMyActivity(ctx context.Context, r store.MyActivityRow) error
	EnrichMyActivityFacets(ctx context.Context, accountID, originKey, repoID, checkpointID string, skills, mcpServers, toolMix, labels []byte) error
}

// Consumer durably pulls user_activity_v1 from its LOCAL region's JetStream
// stream, filtered to this deployment's jurisdiction subject, and writes each
// event into the local personal store.
//
// There is no supercluster: the Publisher in the source region publishes
// directly into the recipient's home-jurisdiction stream, so this consumer
// only ever sees events whose home jurisdiction is this one. recipientIsLocal
// is therefore defense-in-depth — it catches a misrouted publish before a row
// lands in the wrong region.
type Consumer struct {
	nc           *nats.Conn
	store        ActivityWriter
	jurisdiction string
	m            metrics

	// SingleRegion relaxes the residency filter for single-cluster
	// deployments: an event with no stamped home is accepted. In
	// multi-region this MUST stay false so unverifiable events fail closed.
	SingleRegion bool

	cc jetstream.ConsumeContext
}

// NewConsumer constructs a Consumer.
func NewConsumer(nc *nats.Conn, w ActivityWriter, jurisdiction string) *Consumer {
	return &Consumer{nc: nc, store: w, jurisdiction: jurisdiction, m: newMetrics()}
}

// Start creates the durable consumer and begins consuming. Returns
// immediately. The local user_activity_v1 stream must already exist — it is
// provisioned declaratively in fleet (apps/nats-streams, nack), not by this
// binary.
func (c *Consumer) Start(ctx context.Context) error {
	if c == nil || c.nc == nil {
		return errors.New("forwarder: Consumer not initialised")
	}
	if c.store == nil {
		return errors.New("forwarder: Consumer.store required")
	}
	js, err := jetstream.New(c.nc)
	if err != nil {
		return fmt.Errorf("forwarder: jetstream.New: %w", err)
	}
	subject := SubjectUserActivityFor(c.jurisdiction)
	cons, err := js.CreateOrUpdateConsumer(ctx, StreamName, jetstream.ConsumerConfig{
		Durable:       activityDurable,
		AckPolicy:     jetstream.AckExplicitPolicy,
		AckWait:       30 * time.Second,
		MaxDeliver:    activityMaxDeliver,
		FilterSubject: subject,
	})
	if err != nil {
		return fmt.Errorf("forwarder: create consumer %s/%s: %w", StreamName, activityDurable, err)
	}
	cc, err := cons.Consume(func(msg jetstream.Msg) { c.handle(ctx, msg) })
	if err != nil {
		return fmt.Errorf("forwarder: consume %s: %w", subject, err)
	}
	c.cc = cc
	go func() {
		<-ctx.Done()
		_ = c.Stop()
	}()
	slog.InfoContext(ctx, "user_activity consumer started",
		slog.String("jurisdiction", c.jurisdiction), slog.String("subject", subject))
	return nil
}

// Stop halts the consume loop. Idempotent.
func (c *Consumer) Stop() error {
	if c.cc != nil {
		c.cc.Stop()
		c.cc = nil
	}
	return nil
}

func (c *Consumer) handle(ctx context.Context, msg jetstream.Msg) {
	// Re-parent to the source-cluster publish span across the NATS hop.
	ctx, span := natsmsg.StartConsumerSpan(ctx, otelsetup.Tracer(), msg, "user_activity.consume")
	defer span.End()

	var ev UserActivityEvent
	if err := json.Unmarshal(msg.Data(), &ev); err != nil {
		// Poison payload — redelivery won't help. Term so it doesn't cycle.
		span.RecordError(err)
		span.SetStatus(codes.Error, "decode")
		slog.WarnContext(ctx, "forwarder: decode user_activity_v1; term", slog.Any("error", err), slog.String("subject", msg.Subject()))
		_ = msg.Term()
		return
	}
	if ev.Recipient == "" {
		slog.WarnContext(ctx, "forwarder: user_activity_v1 missing recipient; term", slog.String("subject", msg.Subject()))
		_ = msg.Term()
		return
	}
	// Stamp the event identity into baggage so downstream spans (the DB upsert)
	// and logs carry recipient/repo/type.
	ctx = otelsetup.WithBaggage(ctx,
		otelsetup.RecipientAttr(ev.Recipient), otelsetup.RepoIDAttr(ev.RepoID), otelsetup.ActivityTypeAttr(ev.Type))
	if !c.recipientIsLocal(ev) {
		// Should not happen given the placement subject filter; ack so a
		// stray doesn't redeliver forever.
		span.SetAttributes(attribute.String("entire.drop_reason", "foreign_placement"))
		c.m.dropped.Add(ctx, 1, attr("reason", "foreign_placement"))
		_ = msg.Ack()
		return
	}
	// A facet enrichment event carries no row identity/counts — only facets for an
	// already-forwarded checkpoint. Apply it as a facet-columns-only UPDATE keyed
	// on (account, origin, checkpoint), never the row upsert (which would insert a
	// phantom zero-count row and re-count the checkpoint).
	if ev.Type == TypeCheckpointFacets {
		if err := c.store.EnrichMyActivityFacets(ctx, ev.Recipient, store.OriginOf(ev.OriginKey, ev.RepoID), ev.RepoID, ev.CheckpointID,
			ev.Skills, ev.McpServers, ev.ToolMix, ev.Labels); err != nil {
			span.RecordError(err)
			span.SetStatus(codes.Error, "enrich facets")
			slog.WarnContext(ctx, "forwarder: enrich my_activity facets failed; nak", slog.Any("error", err), slog.String("recipient", ev.Recipient))
			_ = msg.Nak()
			return
		}
		c.m.written.Add(ctx, 1, attr("type", ev.Type))
		_ = msg.Ack()
		return
	}
	row := store.MyActivityRow{
		AccountID: ev.Recipient,
		Type:      ev.Type,
		// A pre-v2 producer / unresolved repo sends no origin; the placement id
		// is then the identity — byte-identical to the pre-origin key, so the
		// mixed-version rollout window creates no new row shapes.
		OriginKey:           ev.OriginKey,
		RepoGroupID:         ev.RepoGroupID,
		RepoID:              ev.RepoID,
		Jurisdiction:        ev.Jurisdiction,
		SHA:                 ev.SHA,
		CheckpointID:        ev.CheckpointID,
		CommittedAt:         time.Unix(ev.Timestamp, 0).UTC(),
		Agent:               ev.Agent,
		HasCheckpoint:       ev.HasCheckpoint,
		InputTokens:         ev.InputTokens,
		OutputTokens:        ev.OutputTokens,
		CacheCreationTokens: ev.CacheCreationTokens,
		CacheReadTokens:     ev.CacheReadTokens,
		Steps:               ev.Steps,
		SessionCount:        ev.SessionCount,
		// Re-encode the wire []string ids to the raw-JSON form the spine stores, so
		// the activity read scans them without decoding (only recap decodes them).
		SessionIDs:    store.MarshalSessionIDs(ev.SessionIDs),
		Additions:     ev.Additions,
