		// Transient (DB blip) — nak for redelivery.
		span.RecordError(err)
		span.SetStatus(codes.Error, "upsert")
		slog.WarnContext(ctx, "forwarder: upsert my_activity failed; nak", slog.Any("error", err), slog.String("recipient", ev.Recipient))
		_ = msg.Nak()
		return
	}
	c.m.written.Add(ctx, 1, attr("type", ev.Type))
	_ = msg.Ack()
}

// recipientIsLocal decides whether an event belongs in this region's store.
// Fail closed: a non-empty home that doesn't match is dropped; the no-signal
// case is dropped unless SingleRegion is set.
func (c *Consumer) recipientIsLocal(ev UserActivityEvent) bool {
	if home := ev.RecipientHomeJurisdiction; home != "" {
		return home == c.jurisdiction
	}
	return c.SingleRegion
}

	}
}

// rawOrNil keeps an absent facet column absent on the wire: an empty byte slice
// becomes a nil RawMessage (omitempty drops it) rather than a JSON null, so the
// consumer's COALESCE preserves the stored value instead of the forward clobbering
// it with null.
func rawOrNil(b []byte) json.RawMessage {
	if len(b) == 0 {
		return nil
	}
	return b
}

// JSPublisher is the minimal JetStream publish surface the forwarder needs.
// jetstream.JetStream satisfies it; tests inject a fake. JS publish (not core
// nc.Publish) so each event gets a stream PubAck — the real delivery signal
// behind the nak-on-failure contract — plus the Nats-Msg-Id dedup window.
type JSPublisher interface {
	PublishMsg(ctx context.Context, m *nats.Msg, opts ...jetstream.PublishOpt) (*jetstream.PubAck, error)
}

// Publisher emits user_activity_v1 events into the recipient's HOME region.
//
// There is no supercluster: the publisher holds one JetStream context per
// jurisdiction (conns, keyed by jurisdiction) and publishes directly into the
// home region's stream, mirroring mirror-pipeline's cmd/fanout. A user_activity
// event is account-addressed and an account's residency unit is its
// jurisdiction, so the jurisdiction is the routing key — there is no per-account
// cluster to route by. Residency is enforced by WHICH region the event goes to,
// not by post-hoc filtering. Concurrency-safe (conns is read-only after
// construction) — share one across ingest workers.
type Publisher struct {
	conns        map[string]JSPublisher // jurisdiction -> that region's JetStream
	jurisdiction string                 // this deployment's jurisdiction
	singleRegion bool                   // route unresolved-home events to the local region
	m            metrics
}

// NewPublisher builds a Publisher over a jurisdiction->JetStream map.
// jurisdiction is this deployment's local placement; singleRegion routes
// events with no resolved home to the local region instead of dropping them
// (dev / single-cluster only).
func NewPublisher(conns map[string]JSPublisher, jurisdiction string, singleRegion bool) *Publisher {
	return &Publisher{conns: conns, jurisdiction: jurisdiction, singleRegion: singleRegion, m: newMetrics()}
}

// PublishUserActivity routes an event to its recipient's home region.
//
// Delivery contract (one contract, no "best-effort" ambiguity):
//   - returns nil  => handled: published, OR permanently skipped (no home /
//     unknown region / unroutable). The caller should ACK the source message;
//     redelivery would not change the outcome.
//   - returns err  => TRANSIENT failure (destination NATS unreachable). The
//     caller should NAK the source message so JetStream redelivers and we
//     retry the publish (idempotent downstream upsert makes this safe).
//
// Idempotent at the wire level — the downstream upsert is keyed by
// (account_id, repo_id, sha, type).
func (p *Publisher) PublishUserActivity(ctx context.Context, ev UserActivityEvent) error {
	if p == nil {
		return nil // forwarding disabled (nil publisher, e.g. tests)
	}
	ctx, span := otelsetup.Tracer().Start(ctx, "user_activity.publish",
		trace.WithSpanKind(trace.SpanKindProducer),
		trace.WithAttributes(
			attribute.String("messaging.system", "nats"),
			otelsetup.ActivityTypeAttr(ev.Type),
			otelsetup.RecipientAttr(ev.Recipient),
			otelsetup.RepoIDAttr(ev.RepoID),
		),
	)
	defer span.End()

	// drop records a permanent skip on the span (for trace visibility) and
	// returns nil so the caller acks — redelivery would not change the outcome.
	drop := func(reason string) error {
		span.SetAttributes(attribute.String("entire.drop_reason", reason))
		return nil
	}

	if ev.Recipient == "" {
		// Nothing to route. Permanent — ack.
		p.m.dropped.Add(ctx, 1, attr("reason", "no_recipient"))
		slog.WarnContext(ctx, "forwarder: event missing recipient; skipping", slog.String("subject_root", SubjectUserActivity))
		return drop("no_recipient")
	}

	// Partition-window guard. my_activity is range-partitioned by month on
	// committed_at; a row outside the provisioned window has no partition and
	// would fail to insert downstream (then nak → redeliver → drop). Skip such
	// forwards here — the single funnel for all three forward sites — so the
	// rule can't be bypassed by a future caller. Below the floor = pre-history
	// we don't retain; far future = a bad git committer clock.
	committedAt := time.Unix(ev.Timestamp, 0)
	if committedAt.Before(store.FirstActivityPartition) || committedAt.After(time.Now().Add(store.ActivityFutureMargin)) {
		p.m.dropped.Add(ctx, 1, attr("reason", "out_of_partition_window"))
		slog.WarnContext(ctx, "forwarder: committed_at outside partition window; skipping (out_of_partition_window)",
			slog.String("recipient", ev.Recipient), slog.Time("committed_at", committedAt))
		return drop("out_of_partition_window")
	}

	jur := ev.RecipientHomeJurisdiction
	if jur == "" {
		if !p.singleRegion {
			// Fail closed: an unresolved home placement in multi-region must
			// not be guessed. Permanent skip (re-resolution happens on a fresh
			// ingest/backfill, not redelivery) — ack.
			p.m.dropped.Add(ctx, 1, attr("reason", "unroutable_home_empty"))
			slog.WarnContext(ctx, "forwarder: unresolved home placement in multi-region; dropping (unroutable_home_empty)",
				slog.String("recipient", ev.Recipient))
			return drop("unroutable_home_empty")
		}
		jur = p.jurisdiction // single-region: local placement
	}

	conn, ok := p.conns[jur]
	if !ok {
		// Loud, not silent: a jurisdiction we have no connection for (misconfig
		// or a region not yet rolled out). Permanent for this event — ack.
		p.m.dropped.Add(ctx, 1, attr("reason", "unroutable_jurisdiction"))
		slog.WarnContext(ctx, "forwarder: no NATS connection for home jurisdiction; dropping (unroutable_jurisdiction)",
			slog.String("recipient", ev.Recipient), slog.String("home_jurisdiction", jur))
		return drop("unroutable_jurisdiction")
	}

	ev.SchemaVersion = CurrentSchemaVersion
	body, err := json.Marshal(ev)
	if err != nil {
		// Can't serialize — permanent. Ack.
		p.m.dropped.Add(ctx, 1, attr("reason", "marshal"))
		span.RecordError(err)
		slog.WarnContext(ctx, "forwarder: marshal user_activity_v1 failed; skipping",
			slog.Any("error", err), slog.String("recipient", ev.Recipient))
		return drop("marshal")
	}

	// Nats-Msg-Id is the stable wire identity: a JetStream stream with a
	// Duplicates window collapses genuine re-publishes (redelivery storms)
	// server-side, the same mechanism mirror-pipeline relies on. The
	// recipient accountId lives in the body, not the subject.
	msg := &nats.Msg{
		Subject: SubjectUserActivityFor(jur),
		Data:    body,
		Header:  nats.Header{"Nats-Msg-Id": []string{dedupeID(ev)}},
	}
	span.SetAttributes(
		attribute.String("messaging.destination.name", msg.Subject),
		otelsetup.HomeJurisdictionAttr(jur),
	)
	// Propagate trace context into the message headers so the home-region
	// consumer span parents to this publish span across the NATS hop.
	natsmsg.Inject(ctx, msg)
	// JS publish waits for the home region's stream PubAck — the real
	// delivery signal. On failure (region unreachable, or the stream rejects
	// at MaxBytes under DiscardNew) we surface the error so the caller naks
	// and redelivery retries. The Nats-Msg-Id header drives the dedup window.
	//
	// The publish must be bounded here, not by the caller's ctx: the remote
	// conns reconnect forever (RetryOnFailedConnect / MaxReconnects(-1) in
	// buildClusterConns), and while a region is down nats.go BUFFERS the
	// publish and blocks the PubAck wait until the ctx deadline — jetstream's
	// own 5s default applies only when the ctx has none. Callers run under
	// long budgets (the index-jobs consumer gives each job 10 minutes), so an
	// unbounded publish would let one down region pin every worker slot for
	// the whole outage instead of failing fast into the nak/redeliver path.
	pubCtx, cancel := context.WithTimeout(ctx, publishTimeout)
	defer cancel()
	if _, err := conn.PublishMsg(pubCtx, msg); err != nil {
		p.m.publishErrors.Add(ctx, 1, attr("jurisdiction", jur))
		span.RecordError(err)
		span.SetStatus(codes.Error, "publish failed")
		return fmt.Errorf("forwarder: publish %s into jurisdiction %q: %w", msg.Subject, jur, err)
	}
	p.m.forwarded.Add(ctx, 1, attr("type", ev.Type))
	return nil
}

