package permssweep

import (
	"context"
	"fmt"
	"log/slog"
	"time"

	"github.com/entireio/go-nuts/natsmsg"
	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"

	"entire.io/slogutil"
)

const tracerName = "entire.io/internal/entirecore/permssweep"

// publishTimeout bounds one synchronous PublishMsg round-trip. Load-bearing:
// the enumerator's ctx has no deadline, and an unbounded PubAck wait — with
// RetryOnFailedConnect the connect itself "succeeds" while NATS is down —
// would hang the CronJob forever instead of failing the tick loudly (the
// exact never-terminating-Job failure mode this fan-out exists to kill).
// Deliberately wider than natsmsg's 5s default: a sweep tick fans out many
// publishes and would rather ride out a broker election than fail the run.
const publishTimeout = 15 * time.Second

// JetStreamPublisher is the slice of nats.JetStreamContext the Publisher
// needs, pulled out so tests can stub publish without a live JetStream.
type JetStreamPublisher interface {
	PublishMsg(m *nats.Msg, opts ...nats.PubOpt) (*nats.PubAck, error)
}

// Publisher emits perms_sweep jobs onto the in-cell repo_ops_v1 stream. One
// Publisher per enumerator run; the subject is fixed at construction (the
// sweep is fleet-scoped, so every job of a run rides the same subject).
type Publisher struct {
	js      JetStreamPublisher
	subject string
}

// NewPublisher binds a Publisher to a JetStream context and the enumerator's
// jurisdiction (empty publishes under the "global" token).
func NewPublisher(js JetStreamPublisher, jurisdiction string) *Publisher {
	return &Publisher{js: js, subject: subjectFor(jurisdiction)}
}

// legacyPublisher is the mechanical tail every perms_sweep publish shares —
// enumerator jobs, canaries, and the consumer's chunk continuations: the
// shared natsmsg.LegacyPublisher stamps the JetStream dedup id, injects trace
// context, opens the producer span named operation, and bounds the PubAck
// wait at publishTimeout (see publishTimeout for why the bound is
// load-bearing). Callers own their metrics and logging.
func legacyPublisher(js JetStreamPublisher, operation string) natsmsg.LegacyPublisher {
	return natsmsg.LegacyPublisher{
		JS:        js,
		Tracer:    otel.Tracer(tracerName),
		Timeout:   publishTimeout,
		Operation: operation,
	}
}

// PublishSweep enqueues one per-installation sweep job carrying the
// enumerator's staleness cutoff. The Nats-Msg-Id (op/installation_id)
// collapses same-tick producer retries inside the stream's duplicates
// window; cross-tick duplicates are deliberately allowed and neutralized by
// the worker's consume-time work-list re-check.
func (p *Publisher) PublishSweep(ctx context.Context, installationID int64, staleBefore time.Time) error {
	data, err := encodeEvent(installationID, staleBefore)
	if err != nil {
		return fmt.Errorf("encode sweep job: %w", err)
	}

	msgID := fmt.Sprintf("%s/%d", op, installationID)
	ack, err := legacyPublisher(p.js, "perms.sweep.publish").Publish(ctx,
		&nats.Msg{Subject: p.subject, Data: data}, msgID,
		attribute.Int64("entire.github.installation_id", installationID),
	)
	if err != nil {
		recordInstallationPublished(ctx, "error")
		return fmt.Errorf("publish perms sweep: %w", err)
	}
	recordInstallationPublished(ctx, "ok")
	slogutil.Debug(ctx, "published perms sweep job",
		slog.String("subject", p.subject),
		slog.String("msg_id", msgID),
		slog.Int64("installation_id", installationID),
		slog.Bool("duplicate", ack.Duplicate),
	)
	return nil
}

// PublishCanary enqueues the enumerator's per-run liveness canary (see
// event.Canary). Deliberately NOT counted in installations_published — that
// counter is real sweep throughput. The constant Nats-Msg-Id only collapses
// same-tick producer retries: hourly ticks are far outside the stream's 10s
// duplicates window, so every run's canary is delivered.
func (p *Publisher) PublishCanary(ctx context.Context) error {
	data, err := encodeCanaryEvent()
	if err != nil {
		return fmt.Errorf("encode sweep canary: %w", err)
	}

	msgID := op + "/canary"
	ack, err := legacyPublisher(p.js, "perms.sweep.publish_canary").Publish(ctx,
		&nats.Msg{Subject: p.subject, Data: data}, msgID,
		attribute.Bool("entire.permssweep.canary", true),
	)
	if err != nil {
		return fmt.Errorf("publish perms sweep canary: %w", err)
	}
	slogutil.Debug(ctx, "published perms sweep canary",
		slog.String("subject", p.subject),
		slog.Bool("duplicate", ack.Duplicate),
	)
	return nil
}

