	}}
}

// resyncPushBody is the minimal GitHub push payload mirror-pipeline's fanout
// reads: only repository.full_name and installation.id (see
// ../mirror-pipeline/cmd/fanout/payloads.go). No ref/commits/after — the worker
// syncs AllRefs regardless. The installation id is required so a private
// checkpoints repo can mint an installation token.
type resyncPushBody struct {
	Repository struct {
		FullName string `json:"full_name"`
	} `json:"repository"`
	Installation struct {
		ID int64 `json:"id"`
	} `json:"installation"`
}

// PublishResync builds and publishes the synthetic push webhook for repoID.
//
// DeliveryID buckets on the minute so the stream's ~5-min dedup window collapses
// a burst of resyncs from one busy repo into a single message (the free dedup
// win, not the deferred de-dup subsystem). OTel trace context rides the NATS
// headers so the fanout worker's span parents to this publish.
func (p *resyncWebhookPublisher) PublishResync(ctx context.Context, repoID model.RepoID, fullName string, installationID int64) error {
	var body resyncPushBody
	body.Repository.FullName = fullName
	body.Installation.ID = installationID
	rawBody, err := json.Marshal(body)
	if err != nil {
		return fmt.Errorf("marshal resync push body: %w", err)
	}

	deliveryID := fmt.Sprintf("resync-%s-%d", repoID, time.Now().Unix()/60)
	env := permswebhook.ForwardedWebhook{
		DeliveryID: deliveryID,
		Event:      "push",
		Body:       rawBody,
		ReceivedAt: time.Now(),
	}
	data, err := json.Marshal(env)
	if err != nil {
		return fmt.Errorf("marshal forwarded webhook: %w", err)
	}

	subject := permswebhook.SubjectPrefix + "push"
	ack, err := p.pub.Publish(ctx, &nats.Msg{Subject: subject, Data: data}, deliveryID,
		attribute.String("entire.repo_id", repoID.String()),
		attribute.String("entire.source_full_name", fullName),
	)
	if err != nil {
		return fmt.Errorf("publish resync webhook: %w", err)
	}

	slogutil.Info(ctx, "published mirror resync webhook",
		slog.String("subject", subject),
		slog.String("delivery_id", deliveryID),
		slog.String("repo_id", repoID.String()),
		slog.String("full_name", fullName),
		slog.Int64("installation_id", installationID),
		slog.Bool("duplicate", ack.Duplicate),
	)
	return nil
}

// buildResyncPublisher returns a resync publisher bound to the CENTRAL NATS
// (cfg.NatsURL, where cmd/fanout consumes webhooks_github_v1) plus a cleanup
// that closes the connection. Unlike buildGitJobsPublisher — which requires
// NATS and fails boot — this degrades to a disabled (nil) publisher when
// cfg.NatsURL is unset, so a config without central NATS still boots; resync
// then returns ErrResyncUnavailable (503). In regional/standalone cfg.NatsURL
// is set in practice (the gitjobs publisher already requires a NATS URL).
func buildResyncPublisher(ctx context.Context, cfg Config) (*resyncWebhookPublisher, func(), error) {
	if cfg.NatsURL == "" {
		slogutil.Info(ctx, "mirror resync publisher disabled: ENTIRE_NATS_URL not set")
		return nil, func() {}, nil
	}
	nc, err := connectNATSURL(ctx, cfg, cfg.NatsURL)
	if err != nil {
		return nil, nil, fmt.Errorf("resync nats connect: %w", err)
	}
	js, err := nc.JetStream()
	if err != nil {
		nc.Close()
		return nil, nil, fmt.Errorf("resync jetstream context: %w", err)
	}
	cleanup := func() { drainNATS(ctx, nc, "resync") }
	return newResyncWebhookPublisher(js), cleanup, nil
}

