1	package natsmsg
2	
3	import (
4		"context"
5		"errors"
6		"strings"
7		"testing"
8		"time"
9	
10		natsserver "github.com/nats-io/nats-server/v2/server"
11		"github.com/nats-io/nats.go"
12		"github.com/nats-io/nats.go/jetstream"
13		"go.opentelemetry.io/otel"
14		"go.opentelemetry.io/otel/attribute"
15		"go.opentelemetry.io/otel/codes"
16		"go.opentelemetry.io/otel/propagation"
17		sdktrace "go.opentelemetry.io/otel/sdk/trace"
18		"go.opentelemetry.io/otel/sdk/trace/tracetest"
19		"go.opentelemetry.io/otel/trace"
20	)
21	
22	// testStream is the embedded-server stream the publish tests bind to pub.>.
23	const testStream = "pub_v1"
24	
25	// newStreamConn boots an embedded JetStream server with a stream bound to pub.>
26	// and returns a connection to it — the shared setup for both the modern
27	// (jetstream.New) and legacy (nc.JetStream()) publish paths.
28	func newStreamConn(t *testing.T) *nats.Conn {
29		t.Helper()
30		s, err := natsserver.NewServer(&natsserver.Options{
31			Host:      "127.0.0.1",
32			Port:      -1, // pick a free port
33			NoLog:     true,
34			NoSigs:    true,
35			JetStream: true,
36			StoreDir:  t.TempDir(),
37		})
38		if err != nil {
39			t.Fatalf("new embedded nats server: %v", err)
40		}
41		go s.Start()
42		if !s.ReadyForConnections(10 * time.Second) {
43			t.Fatal("embedded nats server not ready in time")
44		}
45		t.Cleanup(s.Shutdown)
46	
47		nc, err := nats.Connect(s.ClientURL())
48		if err != nil {
49			t.Fatalf("connect: %v", err)
50		}
51		t.Cleanup(nc.Close)
52		js, err := jetstream.New(nc)
53		if err != nil {
54			t.Fatalf("jetstream.New: %v", err)
55		}
56		if _, err := js.CreateStream(context.Background(), jetstream.StreamConfig{
57			Name:       testStream,
58			Subjects:   []string{"pub.>"},
59			Duplicates: time.Minute,
60		}); err != nil {
61			t.Fatalf("create stream: %v", err)
62		}
63		return nc
64	}
65	
66	// runJetStreamEnv boots an embedded JetStream server with a stream bound to
67	// pub.> and returns a modern JetStream context for it.
68	func runJetStreamEnv(t *testing.T) jetstream.JetStream {
69		t.Helper()
70		js, err := jetstream.New(newStreamConn(t))
71		if err != nil {
72			t.Fatalf("jetstream.New: %v", err)
73		}
74		return js
75	}
76	
77	// withTracing installs a recording tracer provider + W3C propagator and returns
78	// the recorder, restoring the previous globals on cleanup. It lets a test
79	// assert the producer span's name and attributes (the global noop tracer records
80	// nothing).
81	func withTracing(t *testing.T) *tracetest.SpanRecorder {
82		t.Helper()
83		prevTP := otel.GetTracerProvider()
84		prevProp := otel.GetTextMapPropagator()
85	
86		rec := tracetest.NewSpanRecorder()
87		tp := sdktrace.NewTracerProvider(sdktrace.WithSpanProcessor(rec))
88		otel.SetTracerProvider(tp)
89		otel.SetTextMapPropagator(propagation.NewCompositeTextMapPropagator(
90			propagation.TraceContext{},
91			propagation.Baggage{},
92		))
93		t.Cleanup(func() {
94			_ = tp.Shutdown(context.Background()) //nolint:errcheck // best-effort tracer-provider shutdown in test cleanup
95			otel.SetTracerProvider(prevTP)
96			otel.SetTextMapPropagator(prevProp)
97		})
98		return rec
